// 跨卷人物的统一简介：同一人物在合集多卷出现时，各卷的字、生卒、简介都以这里为准（势力仍按各卷）。
// 构建时（build.mjs）覆盖各书 PEOPLE_RAW 中的同名人物。简介写此人一生，不限于某一卷。
// 原文引文一律注明出处：**史记|…**、**左传|…**、**汉书|…**、**后汉书|…**；构建时与该书默认出处相同的会去掉前缀。
// 用 node tools/quotes.js _people <史记目录> 左传=… 汉书=… 后汉书=… 核对。
// 同名异人：条目第四项列出适用的卷（书目录名），只覆盖这些卷中的同名人物，其他卷的同名者各写各的；用 commonOf(名, 卷) 取条目。
const PEOPLE_COMMON = {
  // ---------- 西周 · 春秋 ----------
  周幽王: ['', '?–前771', '名宫湦，周宣王之子，西周最后一位天子。在位时三川地震，岐山崩，伯阳甫以为周将亡。他宠爱褒国所献的褒姒，“**史记|褒姒不好笑**”，相传为博她一笑而举烽火召诸侯；又废申后和太子宜臼，改立褒姒之子伯服。申侯联合缯国、犬戎攻周，幽王再举烽火，诸侯不至，被杀于骊山之下，西周灭亡。'],
  褒姒: ['', '?–?', '褒国所献的美女，周幽王的宠妃，生伯服。传说她出自夏代龙漦所化的妖异。“**史记|褒姒不好笑**”，幽王用尽办法，甚至举烽火召来诸侯，她才大笑。幽王因宠爱她废申后、太子宜臼，申侯引犬戎攻破镐京，幽王被杀，褒姒被犬戎掳去，西周因此而亡。'],
  晋献公: ['', '?–前651', '名诡诸，晋武公之子。即位后尽灭曲沃桓叔、庄伯的子孙群公子，作二军，灭耿、霍、魏，用荀息之计“假道于虞以伐虢”，灭虢后回师顺手灭虞，晋国“并国十七，服国三十八”，成为北方大国。晚年宠爱骊姬，逼死太子申生，逐走重耳、夷吾，立骊姬之子奚齐，死后晋国陷入二十年内乱。'],
  申生: ['', '?–前656', '晋献公的太子，母为齐姜。随献公灭耿、霍、魏，又率军攻伐东山皋落氏，屡有战功。骊姬想立自己的儿子，诬告他在祭祀用的胙肉中下毒。有人劝他向献公申辩，他说君父没有骊姬就寝食不安；劝他出走，他说背着弑父的恶名能逃到哪里去，最终自缢于新城，谥恭世子。'],
  荀息: ['', '?–前651', '晋国大夫。献“假道于虞以伐虢”之策，以屈产之乘、垂棘之璧贿赂虞君，晋灭虢、虞后，他牵着原来的马、捧着原来的璧献给献公。献公临终把奚齐托付给他，他立誓以死相报。里克先后杀奚齐、卓子，荀息践诺自杀。'],
  齐桓公: ['', '?–前643', '名小白，齐襄公之弟。襄公被弑后与公子纠争位，被管仲射中带钩，装死抢先回国即位。他捐弃射钩之仇，任用管仲为相，改革内政，北伐山戎救燕，存邢救卫，率诸侯伐楚盟于召陵，葵丘会盟受周天子赐胙，“**史记|九合诸侯，一匡天下**”，是春秋第一位霸主。晚年不听管仲遗言，宠信易牙、竖刁、开方，死后五公子争立，尸体停放六十七日，尸虫爬出门外。'],
  易牙: ['', '?–?', '齐桓公的宠臣，又称雍巫，善于调味烹调。传说桓公说遍尝天下美味，只是没吃过人肉，易牙便烹自己的儿子献给桓公。管仲病重时，桓公问易牙可否为相，管仲说他“**史记|杀子以适君，非人情**”，不可。管仲死后桓公不听其言，仍亲近易牙、竖刁、开方三人专权。桓公病重，三人堵塞宫门，不让人进出，桓公死后，易牙与竖刁杀群吏，立公子无亏，诸公子相攻，桓公的尸体停放六十七日无人收殓。'],
  竖刁: ['', '?–?', '齐桓公的宠臣，为了亲近桓公而自宫做了宦官，管理后宫。管仲病重时，桓公问竖刁可否为相，管仲说他自残其身以媚君，不合人情，难以亲近。管仲死后桓公仍任用他与易牙、开方，三人专权。桓公病重，他们筑高墙堵塞宫门，桓公饥渴而死；死后竖刁与易牙杀群吏，立公子无亏，太子昭出奔宋国，齐国陷入五公子争立的内乱，桓公尸虫出于户。'],
  楚成王: ['', '?–前626', '名頵，楚文王与息妫之子。在位四十六年，北上与齐桓公争衡，齐率诸侯伐楚时派屈完盟于召陵。此后灭弦、黄、英等国，盂之会执宋襄公，泓之战大败宋军，又厚待流亡的晋公子重耳。城濮之战楚军被晋文公击败，北进受挫。晚年想改立太子，被太子商臣（楚穆王）围困，请求吃了熊掌再死而不得，自缢身亡。'],
  百里奚: ['', '?–?', '原为虞国大夫，晋灭虞时被俘，作为秦穆姬的陪嫁之臣送往秦国。他中途逃到楚国，被楚人抓去放牛。秦穆公听说他贤能，怕重金赎买反引起楚人注意，只用五张黑羊皮把他赎回，与他谈论国事三日，授以国政，号“五羖大夫”。他推荐好友蹇叔，二人辅佐秦穆公称霸西戎。'],
  叔向: ['', '?–?', '名羊舌肸，晋国大夫，晋平公的太傅，以博学和直言著称。与郑国子产、齐国晏婴同时，三人常相往来论政。他与晏婴相对感叹晋、齐两国都已进入“季世”，公室衰微而大夫专权；子产铸刑书，他写信反对，认为民知争端，必将弃礼而征于书。'],
  伍举: ['', '?–?', '又称椒举，楚国大夫，伍奢之父，伍子胥的祖父。楚庄王即位三年不出号令，日夜为乐，下令敢谏者死，伍举以“有鸟在于阜，三年不蜚不鸣”的隐语讽谏，庄王答以“三年不蜚，蜚将冲天；三年不鸣，鸣将惊人”。后来他辅佐楚灵王，参与申之会。'],
  晏婴: ['平仲', '?–前500', '字平仲，“**史记|晏平仲婴者，莱之夷维人也**”，晏弱之子，历仕齐灵公、庄公、景公三朝，节俭力行，食不重肉，妾不衣帛，以善谏著称。崔杼弑庄公时，他说“**左传|社稷是主**”，不死不亡，枕尸而哭。出使楚国时以机辩不辱使命；与晋国叔向论齐国将来“**左传|其为陈氏矣**”，预见了田氏代齐。'],
  楚惠王: ['', '?–前432', '名章，楚昭王之子，母为越女。昭王死于城父军中，令尹子西等迎立他，即位时年幼。前 479 年白公胜作乱，杀令尹子西、司马子期，劫持惠王，想自立为王，惠王的侍从屈固背着他逃到昭王夫人宫中，叶公子高率方城以外之兵入郢平乱，惠王复位。他在位五十七年，先后灭陈、蔡、杞、莒，使楚国北境扩展到淮北、泗上；墨子曾到楚国，以止楚攻宋，公输般为楚造云梯，被墨子九拒之。曾侯乙墓出土的镈钟有他为曾侯乙所作的铭文。'],
  智伯: ['', '?–前453', '名瑶，晋国智氏宗主，智宣子之子，正卿，六卿中势力最强。他恃强向韩、魏、赵三家索地，韩、魏都给了，赵襄子不给，智伯便率韩、魏围攻晋阳，引汾水灌城，城中“悬釜而炊，易子而食”。赵襄子派张孟谈暗中说动韩、魏倒戈，三家反攻，智伯兵败被杀，智氏族灭，三家分其地。'],
  赵襄子: ['', '?–前425', '名无恤，赵简子之子，母亲是翟族婢女，因贤能被立为继承人。智伯索地不给，被围于晋阳一年多，派张孟谈联络韩、魏反攻，灭智氏，三分其地，奠定了赵国的基业。他把智伯的头骨漆为饮器，因此遭智伯门客豫让屡次行刺。'],
  韩康子: ['', '?–?', '名虎，韩庄子之子，晋国韩氏宗主。智伯为正卿时，在蓝台宴饮中戏弄韩康子并侮辱其相段规，智国劝智伯说主不备难，难必至矣，智伯不听。智伯向他索地，段规劝他给，使智伯骄而贪，他献出万家之邑。随后又随智伯围攻赵氏于晋阳。智伯引水灌城时说“吾乃今知水之可以亡人国也”，魏桓子以肘撞韩康子，韩康子踩魏桓子之足，因为汾水可灌安邑，绛水可灌平阳。后在张孟谈劝说下与魏桓子倒戈，共灭智氏，三家分其地，为日后韩国立国奠定基础。'],
  魏桓子: ['', '?–?', '名驹，魏襄子之子，晋国魏氏宗主，魏文侯的祖父。智伯向他索地，他起初不给，谋臣任章说无故索地，诸大夫必惧，不如给之，使智伯骄而轻敌，《周书》说将欲败之，必姑辅之，他于是献出万家之邑，随智伯围攻晋阳。智伯引水灌城时说“吾乃今知水之可以亡人国也”，他与韩康子暗中示意，知道安邑、平阳也可被水灌。张孟谈夜出说以唇亡齿寒之理，他与韩康子倒戈，共灭智氏，三分其地。'],
  秦穆公: ['', '?–前621', '名任好，秦德公之子，秦成公之弟，春秋时期秦国最有作为的君主。即位当年“**史记|自将伐茅津，胜之**”，东境抵达黄河。他以五羖羊皮赎回百里奚，又用蹇叔、由余、丕豹、公孙支等人。他三次为晋国立君，晋饥时泛舟输粟，韩原之战俘获晋惠公后又放归，后护送重耳回国即位；又灭梁、芮，尽有河西。殽之战秦军惨败，他素服郊迎，不替孟明，终于济河焚舟、封殽尸而还；又用由余之谋伐戎，益国十二，开地千里，“**史记|遂霸西戎**”。死后以三良等一百七十七人殉葬，国人作《黄鸟》哀之。'],
  卫文公: ['', '?–前635', '名毁，卫昭伯之子，卫懿公的堂弟。前 660 年狄人灭卫，懿公被杀，次年他被齐桓公从齐国送回即位。齐桓公率诸侯在楚丘为卫国筑城，卫文公穿粗布衣、戴粗帛冠，务材训农，通商惠工，敬教劝学，即位时只有兵车三十乘，晚年达到三百乘，卫国得以复兴。重耳流亡经过卫国，他未加礼遇。前 635 年灭同姓的邢国，同年去世。'],
  // ---------- 战国 ----------
  魏惠王: ['', '前400–前319', '名䓨，魏武侯之子，又称梁惠王。即位前与公子缓争位，在浊泽之战中险些被韩、赵所杀。在位前期魏国最强，迁都大梁，开凿鸿沟，召集逢泽之会称王；随后桂陵、马陵两败于齐，太子申被俘，又被秦夺去河西之地，国势转衰，转而与齐威王“徐州相王”。晚年曾召见孟子，问“何以利吾国”。'],
  庞涓: ['', '?–前341', '魏国将军，与孙膑同学兵法，自知才能不及，把孙膑骗到魏国，以罪处以膑刑并黥面。率军攻拔邯郸，被孙膑“围魏救赵”，在桂陵败于齐军。十三年后马陵之战，中孙膑减灶诱敌之计，追入马陵道，树下见白书，万弩俱发，自刭前叹道“**史记|遂成竖子之名**”。'],
  齐威王: ['', '?–前320', '名因齐，即位之初沉湎酒乐，不理政事，淳于髡以“国中有大鸟，三年不蜚又不鸣”讽谏，他答“**史记|一鸣惊人**”，于是烹阿大夫、封即墨大夫，齐国大治。任用邹忌为相，田忌为将，孙膑为军师，桂陵、马陵两败魏国，与魏惠王“徐州相王”，使齐国成为东方强国。'],
  孙膑: ['', '?–?', '孙武的后世子孙，与庞涓同学兵法。被庞涓陷害，受膑刑并黥面，齐国使者把他偷偷载回齐国。他为田忌出“**史记|今以君之下驷与彼上驷**”的赛马之策，被荐于齐威王，拜为军师。桂陵之战“围魏救赵”，马陵之战减灶诱敌，两败魏军，“**史记|孙膑以此名显天下，世传其兵法**”。'],
  田忌: ['', '?–?', '齐国将领，田氏宗族。他常与齐威王及诸公子赛马，孙膑看出马分上中下三等，教他以下驷对上驷、以上驷对中驷、以中驷对下驷，三局两胜，赢得千金，于是他把孙膑推荐给齐威王，威王拜孙膑为师。前 353 年桂陵之战、前 341 年马陵之战，他都任齐军主将，用孙膑之计“围魏救赵”、减灶诱敌，两次大败魏军。后来与相国邹忌不和，邹忌派人在市上占卜，诬他谋反，他攻临淄不克，出奔楚国，齐宣王时复召回。'],
  秦孝公: ['', '前381–前338', '名渠梁，秦献公之子。即位时秦国僻处雍州，诸侯“夷翟遇之”，他发布求贤令，说“**史记|宾客群臣有能出奇计彊秦者，吾且尊官，与之分土**”。卫鞅由魏入秦，孝公重用他两次变法，迁都咸阳，奖励耕战，推行县制，使秦国由西陲弱国一跃成为强国。'],
  商鞅: ['', '约前390–前338', '卫国公族，名鞅，又称卫鞅，“**史记|少好刑名之学**”。先事魏相公叔痤，公叔痤临终劝魏惠王或用之或杀之，惠王都没听。他入秦后得秦孝公重用，徙木立信，两次变法，奖励耕战，推行县制，开阡陌，统一度量衡，奠定秦国富强的基础，受封商於十五邑，号商君。孝公死后被诬谋反，逃亡时客舍不敢收留没有凭证的人，他叹道“**史记|为法自毙一至此哉**”，最终被车裂。'],
  秦昭襄王: ['', '前325–前251', '名稷，秦武王的异母弟，武王举鼎绝膑而死时在燕国为质，被迎回即位，在位五十六年，是在位最久的秦王。前期由母亲宣太后与舅舅魏冉掌权，白起伊阙之战、拔郢、华阳之战屡破诸侯；后用范雎“**史记|远交而近攻**”之策，废逐穰侯，收回大权。长平之战歼灭赵军主力，又灭西周，奠定了秦统一天下的基础。'],
  白起: ['', '?–前257', '郿人，秦国名将，善用兵。伊阙之战斩韩魏联军二十四万，攻破楚都郢、火烧夷陵，华阳之战斩首十三万，封武安君。长平之战诱围赵括，坑杀赵卒四十万。此后与范雎不和，称病不肯再攻邯郸，被贬为士卒，迁往阴密，在杜邮被秦王赐剑自杀，死前说长平坑杀降卒数十万，“**史记|我固当死**”。'],
  范雎: ['叔', '?–前255', '魏人，曾为魏中大夫须贾的门客，随须贾出使齐国，被怀疑私通齐国，魏相魏齐命人笞击，打断肋骨牙齿，扔进厕中。他装死逃出，改名张禄入秦，向昭王提出“**史记|远交而近攻**”之策，废逐穰侯，任秦相，封应侯。为人“**史记|一饭之德必偿，睚眦之怨必报**”。长平之战以反间计使赵用赵括；后来所荐之人郑安平、王稽相继获罪，他让相位于蔡泽。'],
  信陵君: ['', '?–前243', '名无忌，魏昭王之子，魏安釐王的异母弟，战国四公子之一。礼贤下士，“**史记|致食客三千人**”，亲自驾车“**史记|虚左，自迎夷门侯生**”。邯郸之围时用侯嬴之计，请如姬窃得兵符，命朱亥椎杀晋鄙，夺军救赵，此后留赵十年。秦攻魏，他回国率五国之兵在河外大破秦军。晚年被魏王猜忌，纵情酒色，四年后病逝。'],
  侯嬴: ['', '?–前257', '魏都大梁夷门的看门人，七十岁，家贫。信陵君亲自驾车“**史记|虚左，自迎夷门侯生**”，他故意让信陵君在市中久等以观其诚意。邯郸之围时献窃符救赵之计，并推荐屠夫朱亥同行；他说自己年老不能随行，约定在信陵君到达晋鄙军中之日，面向北方自刭相送。'],
  朱亥: ['', '?–?', '大梁市井中的屠夫，有勇力，侯嬴称他是隐于屠间的贤者。信陵君几次登门拜访，他都故意不回礼，信陵君颇感奇怪。邯郸之围时，信陵君窃得兵符北上，侯嬴说将在外，主令有所不受，晋鄙若不听，可使朱亥击之。信陵君去请他，他笑说臣乃市井鼓刀屠者，而公子亲数存之，所以不报谢者，以为小礼无所用，今公子有急，此乃臣效命之秋也。随信陵君至邺，晋鄙合符后仍有怀疑，朱亥“**史记|袖四十斤铁椎，椎杀晋鄙**”，信陵君得以统兵救赵。据《史记正义》引《列士传》，他后来出使秦国，被秦王置于虎圈，怒目视虎，虎不敢动。'],
  平原君: ['', '?–前251', '名胜，赵武灵王之子，赵惠文王之弟，战国四公子之一，门下食客数千人，“**史记|相赵惠文王及孝成王，三去相，三复位**”。主张接受韩国上党之地，引发长平之战。邯郸被围时赴楚求援，带门客毛遂同行，毛遂按剑逼楚王订立合纵；回国后又散家财募敢死之士三千人，与李同等抵抗秦军，坚持到魏、楚援军到来。'],
  蔺相如: ['', '?–?', '赵国宦者令缪贤的门客。秦昭王以十五城换和氏璧，他奉璧入秦，见秦王无意给城，以计完璧归赵；渑池之会迫秦王为赵王击缻，拜为上卿，位在廉颇之上。廉颇不服，扬言要羞辱他，他处处避让，说“**史记|吾所以为此者，以先国家之急而后私雠也**”，廉颇负荆请罪，二人成为刎颈之交。长平之战时他已病重，仍劝赵王不可用赵括，说他“**史记|若胶柱而鼓瑟耳**”。'],
  廉颇: ['', '?–?', '赵国良将，“**史记|以勇气闻于诸侯**”。不服蔺相如位居其上，得知其以国家为重的用心后“**史记|肉袒负荆**”谢罪，结为刎颈之交。长平之战坚壁拒秦，被赵王以赵括取代；后来在鄗大破燕军，封信平君。赵悼襄王以乐乘代之，他出奔魏、楚，赵王想再用他，派使者探看，使者受郭开贿赂，回报“**史记|廉将军虽老，尚善饭**，然与臣坐，顷之三遗矢矣”，最终死于寿春。'],
  春申君: ['', '?–前238', '名歇，姓黄，楚国令尹，战国四公子之一，门下食客三千人。曾陪太子完在秦国为质，楚顷襄王病重时，设计让太子化装逃回楚国即位，是为楚考烈王，他自己留秦请死，被秦王放归。任令尹二十余年，北伐灭鲁，主持战国最后一次合纵攻秦。考烈王死后，在棘门被李园伏兵刺杀，满门被灭。'],
  // ---------- 秦 · 楚汉 ----------
  李斯: ['', '?–前208', '楚国上蔡人，年轻时为郡小吏，见仓中鼠“**史记|食积粟，居大庑之下，不见人犬之忧**”，感叹人之贤愚在于所处之地，于是从荀子学帝王之术，入秦为吕不韦舍人。秦王下令逐客时上《谏逐客书》，言“**史记|太山不让土壤，故能成其大**”。辅佐秦王统一天下，主张郡县制、统一文字、焚书，官至丞相。沙丘之变中与赵高合谋立胡亥，后被赵高诬陷，腰斩于咸阳，临刑对儿子有“**史记|上蔡东门逐狡兔**”之叹。'],
  赵高: ['', '?–前207', '秦国宦官，通晓狱法，任中车府令，“**史记|行符玺事**”，曾教公子胡亥书法与狱律。秦始皇死于沙丘，他与李斯合谋伪造遗诏，赐死扶苏，立胡亥为二世皇帝。此后构陷李斯，代为丞相，独揽大权，“**史记|持鹿献于二世**”，指鹿为马以试探群臣。刘邦入关后，他弑杀二世，立子婴为秦王，旋即被子婴设计刺杀。'],
  秦二世: ['', '前230–前207', '名胡亥，秦始皇少子，曾从中车府令赵高学习书法和狱律令法，深得始皇宠爱。前 210 年随始皇出巡，始皇死于沙丘，“**史记|独子胡亥、赵高及所幸宦者五六人知上死**”，他与赵高、李斯合谋篡改遗诏，赐死长子扶苏与蒙恬，即位为二世皇帝。他听赵高之言，诛杀蒙恬、蒙毅，杀害兄弟姊妹二十余人，继续修阿房宫、骊山陵，征发闾左戍边，前 209 年陈胜吴广起事，天下大乱。他深居宫中，政事委于赵高，赵高指鹿为马，又诬杀李斯。前 207 年在望夷宫被赵高之婿阎乐逼杀，年二十四，以黔首之礼葬于杜南宜春苑中。'],
  赵佗: ['', '?–前137', '“**史记|南越王尉佗者，真定人也，姓赵氏**。”秦平岭南后任南海郡龙川令，受南海尉任嚣临终嘱托代行郡事。秦亡后封关绝道，兼并桂林、象郡，自立为南越武王。汉初陆贾出使，他接受汉朝所封的南越王印；吕后禁止向南越出售铁器，他称南越武帝，发兵攻长沙；文帝时陆贾再使，他去帝号称臣。享寿极长，历经秦始皇到汉武帝初年。'],
  张良: ['子房', '?–前186', '韩国相门之后，“**史记|大父开地，相韩昭侯、宣惠王、襄哀王**”。秦灭韩后散尽家财求刺客，在博浪沙狙击秦始皇，误中副车，逃匿下邳，在圯上为老人拾履，得授《太公兵法》。归刘邦后，峣关之计、鸿门脱险、烧绝栈道、下邑画策、借箸阻立六国后、固陵之策皆出其手，刘邦称“**史记|夫运筹策帷帐之中，决胜于千里之外，吾不如子房**”。汉初封留侯，劝先封雍齿以安群臣、定都关中，为吕后请来商山四皓保住太子。晚年杜门学辟谷，说“**史记|愿弃人间事，欲从赤松子游耳**”。'],
  刘邦: ['季', '前256–前195', '沛县丰邑中阳里人，“**史记|隆准而龙颜，美须髯**”，为人仁而爱人，喜施舍，不事生产。曾任泗水亭长，在咸阳见到秦始皇出巡，叹道“**史记|嗟乎，大丈夫当如此也**”。秦末起兵于沛，先入关中，受封汉王；与项羽相争五年，善于用人纳谏，垓下灭楚，前 202 年称帝，是为汉高祖。在位八年间平定异姓诸侯王，白登被围后与匈奴和亲，大封同姓子弟为王，确立了郡国并行的格局。'],
  萧何: ['', '?–前193', '沛县人，以文吏起家，任沛县主吏掾，是刘邦的同乡与开国功臣之首。入咸阳时诸将争夺金帛，他“**史记|先入收秦丞相御史律令图书藏之**”，汉由此掌握天下形势；又月下追回韩信，力荐拜将。楚汉相争时坐镇关中，发兵运粮从未断绝，刘邦称“**史记|镇国家，抚百姓，给餽馕，不绝粮道，吾不如萧何**”。汉初论功第一，封酂侯，任相国，制定律令，营建未央宫；晚年为避刘邦猜疑，故意强买民田以自污。'],
  韩信: ['', '?–前196', '淮阴人，少时贫困，曾受漂母之食，又受市井少年“**史记|出我袴下**”之辱。先投项梁、项羽不被重用，归汉后经萧何力荐拜为大将。此后平魏、破代、背水灭赵、降燕、定齐，垓下合围项羽，刘邦称其“**史记|连百万之军，战必胜，攻必取，吾不如韩信**”。汉朝建立后先封楚王，被告谋反，陈平献计伪游云梦将他擒获，贬为淮阴侯，叹道“**史记|狡兔死，良狗亨**”。陈豨反时被吕后与萧何诱入长乐宫钟室斩杀，夷三族。'],
  曹参: ['敬伯', '?–前190', '沛县人，秦时为沛县狱掾，与萧何同为县中豪吏。随刘邦起兵后攻城略地，身被七十创；楚汉相争时随韩信平魏、破赵、击齐，战功在诸将之首。汉初任齐国丞相九年，用盖公的黄老之术治齐，齐国安定。萧何死后入朝为相国，“**史记|举事无所变更，一遵萧何约束**”，日夜饮酒，后世称“萧规曹随”。'],
  樊哙: ['', '?–前189', '沛县人，“**史记|以屠狗为事**”，与刘邦一同隐匿芒砀山，娶吕后之妹吕媭，是刘邦的连襟。鸿门宴上持盾闯帐，“**史记|瞋目视项王**，头发上指，**史记|目眦尽裂**”，饮卮酒、啖彘肩，斥项羽欲诛有功之人，护刘邦脱身。汉初随刘邦平定臧荼、韩王信、陈豨，封舞阳侯。刘邦晚年疑其党附吕氏，命陈平就军中斩之，陈平只将他押回，恰逢刘邦去世，得以获释。'],
  夏侯婴: ['', '?–前172', '沛县人，在县府管理车马，与刘邦交好，起兵后常为刘邦驾车，因任滕令，号“滕公”。韩信犯法当斩时，他见韩信言谈不凡，救下并推荐给刘邦。彭城之败，刘邦几次把子女推下车，“**史记|滕公常下收载之**”，保全了后来的汉惠帝和鲁元公主。白登之围时为刘邦驾车突围。任太仆，历事高祖、惠帝、吕后、文帝，诛诸吕后与刘兴居一同清宫，迎文帝入宫。'],
  陈平: ['', '?–前178', '阳武户牖乡人，少时家贫好读书，社祭时分肉公平，乡里称赞。先后事魏王咎、项羽，后归汉，任护军中尉。以黄金四万斤行反间，使项羽疏远范增；荥阳之围时配合纪信诈降；汉初又设计伪游云梦擒韩信、贿赂阏氏解白登之围，“**史记|凡六出奇计**”。吕后时任右丞相，表面顺从吕氏，暗中与周勃谋划，诛诸吕、迎立文帝。'],
  灌婴: ['', '?–前176', '“**史记|颍阴侯灌婴者，睢阳贩缯者也**。”随刘邦起兵后以骁勇屡立战功，楚汉相争时统率郎中骑兵，成为汉军骑兵统帅，随韩信破齐、斩龙且，又率骑兵追击项羽至东城。封颍阴侯。吕后死后奉命迎击起兵的齐王，却在荥阳按兵不动，与齐王联络共诛诸吕。文帝时继周勃任丞相。'],
  吕后: ['娥姁', '前241–前180', '名雉，单父人吕公之女，吕公善相人，认为刘邦有贵相，将她嫁给刘邦。彭城之败后被楚军俘虏，在楚营为人质两年多。汉朝建立后立为皇后，参与诛杀韩信、彭越。惠帝即位后以“人彘”残害戚夫人，毒死赵王如意；惠帝死后临朝称制八年，大封诸吕为王。《史记》为她单列本纪，称其时“**史记|政不出房户，天下晏然**”。'],
  彭越: ['仲', '?–前196', '昌邑人，“**史记|常渔巨野泽中，为群盗**”。秦末聚众起事，号令严明。归汉后长期在楚军后方的梁地游击，屡断楚军粮道，攻下睢阳、外黄等十七城，使项羽疲于奔命。垓下之战率兵会合，汉朝建立后封梁王。陈豨反时称病不往，被告谋反，废为庶人徙蜀，途中遇吕后，求她说情，吕后却带他回洛阳，劝刘邦将他诛杀，剁成肉酱遍赐诸侯。'],
  英布: ['', '?–前196', '六县人，少时有人为他看相，说他“**史记|当刑而王**”，后果然犯法受黥刑，人称黥布。被押往骊山服役，结交豪杰，逃入江中为群盗。归项梁后常为楚军先锋，巨鹿之战先渡河破秦，又奉命坑杀秦降卒，被封为九江王。后被随何说服归汉，封淮南王，参加垓下之战。韩信、彭越相继被杀后起兵反叛，兵败后被长沙王吴臣诱杀。'],
  臧荼: ['', '?–前202', '原为燕王韩广部将，随项羽救赵、入关，被封为燕王，后击杀被迁往辽东的韩广，兼并其地。韩信破赵后用李左车之计遣使劝降，臧荼降汉。汉朝建立当年起兵反叛，被刘邦亲征擒获。他的孙女臧儿是汉武帝的外祖母。'],
  // ---------- 西汉 ----------
  汉武帝: ['', '前156–前87', '名刘彻，景帝之子，母王夫人。四岁封胶东王，栗太子被废后立为太子，十六岁即位，在位五十四年。他任用卫青、霍去病北击匈奴，收河南、开河西，派张骞通西域，平南越、东越、西南夷、朝鲜，开疆拓土；内设十三刺史部，行推恩令，尊儒术，兴太学；为筹军费行盐铁官营、均输平准、算缗告缗。晚年求仙封禅，巫蛊之祸逼死太子刘据，征和四年下轮台诏，“**汉书|深陈既往之悔**”。'],
  窦太后: ['', '?–前135', '文帝皇后，清河观津人，出身贫寒，以良家子入宫，被赐给代王，生景帝与梁孝王。好黄帝、老子之言，景帝及诸窦都不得不读《老子》。偏爱小儿子梁王刘武，一度想立他为景帝的继承人。武帝即位后为太皇太后，“**史记|窦太后治黄老言，不好儒术**”，建元二年罢黜赵绾、王臧，武帝初年的新政因此中止。'],
  窦婴: ['王孙', '?–前130', '窦太后堂兄之子，喜宾客。景帝酒后说要传位梁王，他当面反对，被窦太后除去门籍。七国之乱时任大将军，屯兵荥阳监齐、赵兵，封魏其侯。武帝初任丞相，与田蚡共推儒术，赵绾、王臧事发后罢相。窦太后死后失势，门客散尽，只有灌夫与他交好如故；为营救骂座的灌夫与田蚡廷辩，被弃市于渭城。'],
  李广: ['', '?–前119', '陇西成纪人，世代传习射箭。文帝时以良家子从军击匈奴，景帝时历任北边七郡太守，匈奴号为“飞将军”，数年不敢入右北平。曾以百骑解鞍诱敌退匈奴数千骑；龙城之战兵败被俘，装死夺马逃回。一生与匈奴大小七十余战，始终未能封侯。漠北之战被调出主力，迷失道路，说“**史记|且年六十余矣，终不能复对刀笔之吏**”，引刀自刭，百姓闻之无不垂涕。'],
  韩安国: ['长孺', '?–前127', '梁国成安人，梁孝王的中大夫。七国之乱时与张羽守睢阳，又为梁王出使长安，向景帝和窦太后陈说梁王的忠孝，化解兄弟嫌隙。后坐法下狱，狱吏田甲侮辱他，他说“**史记|死灰独不复然乎**”，不久被起用为梁内史。武帝时任御史大夫，主张和亲，反对马邑之谋；晚年屯兵渔阳，被匈奴击败，忧郁吐血而死。'],
  桑弘羊: ['', '前152–前80', '洛阳商人之子，十三岁以善于心算入宫为侍中。元封元年起领大农，主持盐铁官营、均输、平准、算缗，“**史记|民不益赋而天下用饶**”，支撑了武帝一朝的连年用兵。武帝临终拜御史大夫，受遗诏辅佐昭帝。盐铁会议上与贤良文学辩论，坚持官营；后为子弟求官不得，与上官桀、燕王旦同谋，被诛。'],
  苏武: ['子卿', '前140–前60', '杜陵人，苏建之子。天汉元年以中郎将持节出使匈奴，副使张胜卷入谋乱，他被扣留。卫律威逼利诱，他不为所动，被幽禁大窖中，嚼雪吞毡毛不死，又被迁到北海牧羊，“**汉书|杖汉节牧羊，卧起操持，节旄尽落**”。始元六年归汉，“**汉书|武留匈奴凡十九歳，始以强壮出，及还，须发尽白**”，拜典属国，宣帝时图像列于麒麟阁。'],
  李陵: ['少卿', '?–前74', '李广之孙，善骑射，爱人下士。天汉二年自请率步卒五千出居延，在浚稽山与单于三万骑激战，且战且退，杀伤万余人，箭尽粮绝，离汉塞百余里而援军不至，说“**汉书|无面目报陛下**”，投降匈奴。一年多后武帝误信他为匈奴练兵，族诛其母亲妻子，司马迁为他辩护而受宫刑。他娶单于之女，封右校王，留居匈奴二十余年，昭帝时霍光派人招他回汉，他终未归。'],
  霍光: ['子孟', '?–前68', '霍去病异母弟，十余岁入宫，侍奉武帝二十余年，“**汉书|小心谨慎，未甞有过**”。武帝临终拜大司马大将军，与金日磾、上官桀、桑弘羊共同辅佐八岁的昭帝，“**汉书|政事壹决于光**”。他挫败上官桀、燕王旦之谋，昭帝死后迎立昌邑王刘贺，二十七日后又将其废黜，迎立宣帝，秉政前后二十年。死后两年，霍氏因谋反族诛。宣帝图画功臣于麒麟阁，以他为首。'],
  金日磾: ['翁叔', '前134–前86', '匈奴休屠王太子，十四岁时浑邪王杀休屠王降汉，他没入官府为马奴，因养马肥好、容貌威严被武帝擢用，赐姓金。为人笃慎，长子与宫人戏，他亲手杀之。后元元年马何罗谋逆，他抱住刺客，高呼“**汉书|莽何罗反**”，护驾有功。受武帝遗诏为车骑将军辅佐昭帝，一年多后去世。'],
  上官桀: ['少叔', '?–前80', '陇西上邽人，少时为羽林郎，以力大善骑射得武帝赏识，后为太仆，受遗诏为左将军，与霍光共同辅政，两家结为儿女亲家，孙女立为昭帝皇后。后为上官氏请封、为门客求官，屡被霍光拒绝，与燕王旦、桑弘羊、鄂邑长公主勾结，谋杀霍光、废昭帝，事泄族诛。'],
  汉昭帝: ['', '前94–前74', '名刘弗陵，武帝少子，母钩弋夫人，号钩弋子，相传怀胎十四月而生。巫蛊之祸后被立为太子，八岁即位，委政霍光。十四岁时识破燕王上书诬告霍光之诈，说“**汉书|燕王何以得知之**”。在位十三年，罢酒榷，开盐铁会议，与匈奴和亲，与民休息，二十一岁去世，无子。'],
  刘歆: ['子骏', '?–23', '刘向之子，少通《诗》《书》，成帝时与父亲一同校书，父死后继承其业，撰成中国第一部综合性图书分类目录《七略》，推崇《左传》《周礼》等古文经学。哀帝时与王莽同为黄门郎，王莽秉政后为国师，参与制定改制方案。地皇四年与王涉、董忠谋劫王莽降汉，事泄自杀。'],
  王政君: ['', '前71–13', '魏郡元城人，入宫后曾被冷落，偶然被选送太子宫，生下成帝，元帝时立为皇后，成帝时为皇太后。历元、成、哀、平四朝，王氏一门因她而贵，九人封侯，五人任大司马。哀帝死后她收取玺绶，召王莽主政，王莽借她的权威一步步代汉。王莽索要传国玉玺时，她怒骂后把玉玺扔在地上，摔崩一角；新朝建立后始终不肯改用新朝服色。'],
  孺子婴: ['', '5–25', '名刘婴，宣帝玄孙，广戚侯刘显之子。平帝死后，两岁的他被王莽选为嗣，号孺子，王莽居摄称假皇帝。王莽即真后，封他为定安公，幽禁于大鸿胪府，不许乳母与他说话，长大后不能分辨六畜。更始三年，方望等把他拥立于临泾，被更始派兵击杀。'],
  王莽: ['巨君', '前45–23', '王政君之侄，父亲早死，没有封侯，事母及寡嫂、养兄子，折节恭俭，勤学博览，“**汉书|爵位益尊，节操愈谦**”。三十八岁为大司马，哀帝时退归新都，平帝时复出，号安汉公、宰衡，平帝死后居摄称假皇帝，初始元年代汉建新。在位十五年，托古改制，行王田、私属、五均六筦、宝货诸制，改易官名地名，贬降四夷王号，天下大乱。地皇四年长安城破，死于渐台，“**汉书|商人杜吴杀莽**”。'],
  // ---------- 东汉 ----------
  刘秀: ['文叔', '前5–57', '字文叔，南阳蔡阳人，汉高祖九世孙，九岁丧父，为叔父所养，“**后汉书|性勤于稼穑**”。地皇三年与兄刘縯起兵，昆阳之战以数千人大破王莽四十余万大军。刘縯被杀后隐忍不露，持节北渡河，平王郎、降铜马，建武元年即位于鄗，定都洛阳。此后十二年间削平赤眉、刘永、隗嚣、公孙述等群雄，“**后汉书|退功臣而进文吏，戢弓矢而散马牛**”，度田核户，省并郡县，南定交趾，北纳南匈奴。在位三十三年，中元二年崩，庙号世祖。'],
  郭圣通: ['', '?–52', '真定藁人，郭昌之女，母亲是真定恭王之女。刘秀在河北时，为结好拥兵十余万的真定王刘杨，娶刘杨的外甥女郭圣通，得到刘杨的兵力相助，才得以击破王郎。建武二年立为皇后，其子刘彊立为太子。后来她“数怀怨怼”，建武十七年被废为中山王太后，太子刘彊让位。光武对郭氏仍加恩宠，其弟郭况家号为“金穴”。建武二十八年去世。'],
  汉明帝: ['', '28–75', '名庄，原名阳，光武第四子，母阴丽华。十二岁时在幄后点破陈留吏牍上“**后汉书|颍川、弘农可问，河南、南阳不可问**”的缘由，光武大为惊奇。建武十九年代刘彊为太子，中元二年即位。他遵奉光武制度，吏治严切，不许外戚封侯干政，亲临辟雍讲经。永平年间遣使求佛法，使王景治河，又遣窦固伐北匈奴，班超出使西域，复置西域都护。在位十八年，永平十八年崩，庙号显宗。'],
  邓禹: ['仲华', '2–58', '字仲华，南阳新野人，十三岁能诵诗，在长安受业时与刘秀相亲。刘秀北渡河后，他杖策追到邺城，劝刘秀延揽英雄、务悦民心，以图天下，刘秀恃之为萧何。建武元年西征关中，拜大司徒，年仅二十四岁，入长安后屡败于赤眉，交还印绶。天下既定，他主动交出兵权，以特进奉朝请，教十三个儿子各守一艺，修整闺门。明帝即位拜为太傅，永平元年卒，位列云台二十八将之首。'],
  冯异: ['公孙', '?–34', '字公孙，颍川父城人，好读书，通《左传》《孙子兵法》，王莽时为郡掾，以父城降刘秀。刘秀河北危难时，他在芜蒌亭献豆粥，在南宫献麦饭。为人谦退不伐，诸将并坐论功，他常独坐树下，军中号为“**后汉书|大树将军**”。建武二年代邓禹西征，在崤底大破赤眉，光武称他“**后汉书|失之东隅，收之桑榆**”。此后镇守关中，有人奏他威权太重，号为“咸阳王”，光武不疑。建武十年攻落门时病死军中。'],
  耿弇: ['伯昭', '3–58', '字伯昭，扶风茂陵人，上谷太守耿况之子，少好学，喜将帅之事。二十一岁奉父命去长安谒见更始，途中转投刘秀，说服父亲与渔阳彭宠发突骑南下，助刘秀平定河北。光武即位后拜建威大将军，东征张步，攻破临淄，平定齐地十二郡，光武称赞他“**后汉书|有志者事竟成也**”。此后随征陇右，攻下落门。建武十三年上大将军印绶，以列侯奉朝请，每有大议常被召问。永平元年卒。'],
  吴汉: ['子颜', '?–44', '字子颜，南阳宛人，家贫，王莽末年亡命渔阳，以贩马为业。王郎起兵时，他劝渔阳太守彭宠归附刘秀，率突骑南下，光武即位后拜大司马。为人质厚少文，“**后汉书|每当出师，朝受诏，夕即引道，初无办严之日**”，光武称他“**后汉书|隐若一敌国矣**”。先后平檀乡、刘永、董宪，又溯江伐蜀，建武十二年攻破成都，因纵兵大掠受光武严责。建武二十年卒，是东汉开国第一战将。'],
  岑彭: ['君然', '?–35', '字君然，南阳棘阳人，王莽时为棘阳长，在宛城被汉军围困数月后投降，先后事刘縯、朱鲔，后来投奔刘秀。建武元年到洛阳城下劝降昔日上司朱鲔，使洛阳不战而下。此后讨平荆州诸郡，随征陇右。建武十一年在荆门火烧蜀军浮桥，长驱入江关，又倍道兼行二千余里直抵武阳，逼近成都。扎营之地名为“彭亡”，他“**后汉书|闻而恶之，欲徙**”，当夜被公孙述所派刺客诈降刺杀。'],
  窦融: ['周公', '前16–62', '字周公，扶风平陵人，文帝窦皇后之弟窦广国的七世孙，家族累世在河西为官。王莽败后，他认为河西殷富，带河为固，足以自守，求为张掖属国都尉，被河西五郡豪杰推为行河西五郡大将军事，保境安民。建武五年“**后汉书|遂决策东向**”，归附光武，八年率五郡兵会光武于高平，共破隗嚣。后入朝任大司空，窦氏“**后汉书|一公、两侯、三公主、四二千石**”。晚年子孙多不法，永平五年卒，年七十八。'],
  樊崇: ['细君', '?–27', '字细君，琅邪人。天凤五年因饥荒在莒县起兵，转入太山，自号三老，一年间众至万余人，相约“**后汉书|杀人者死，伤人者偿创**”。地皇三年在成昌大破莽军，因“**后汉书|乃皆朱其眉以相识别，由是号曰赤眉**”。更始立后曾入洛阳归附，不久离去，率众西进，立刘盆子为帝，建武元年攻入长安。次年因关中饥荒东归，建武三年在宜阳被光武围困，肉袒投降，同年夏因谋反被杀。'],
  刘盆子: ['', '10–?', '太山式人，城阳景王刘章之后，父亲式侯刘萌。王莽篡位后国除，他与兄长刘恭被赤眉军掠去，在军中放牛。赤眉入关时，军中巫师说城阳景王大怒，应立刘氏为帝，樊崇等找到城阳景王后裔七十余人，选三人探符，十五岁的他最小，探得“上将军”，被立为皇帝，建元建世。建武三年随赤眉降光武，光武赏赐甚厚，任为赵王郎中，后因病失明，赐荥阳均输官地，令他以食税终身。'],
  刘永: ['', '?–27', '梁孝王刘武的八世孙，父亲梁王刘立被王莽所杀。更始立后，他到洛阳朝见，复封梁王，都睢阳。更始政乱时据国起兵，招揽沛人周建等豪杰，攻下济阴、山阳、沛、楚、淮阳、汝南等二十八城，又封张步为齐王、董宪为海西王，割据关东。建武元年称帝，与光武相争，被盖延围困睢阳，城破后出逃，建武三年被部将庆吾斩杀。其子刘纡继续与董宪据守东海，五年被吴汉所获。'],
  张步: ['文公', '?–32', '字文公，琅邪不其人，王莽末年聚众数千，攻下附近县城，自称五威将军，据有琅邪。刘永自立后封他为辅汉大将军，他于是攻取太山、东莱、城阳、胶东、北海、济南、齐诸郡，割据齐地十二郡。光武派伏隆招抚，他已受刘永封为齐王，杀了伏隆。建武五年被耿弇在临淄大破，在平寿“**后汉书|乃肉袒负斧锧于军门**”，封安丘侯。八年想逃回琅邪起事，被琅邪太守陈俊追斩。'],
  隗嚣: ['季孟', '?–33', '字季孟，天水成纪人，少仕州郡，为王莽国师刘歆的属官，以知书通经闻名陇西。昆阳之战后被叔父隗崔等推为上将军，攻下陇右、河西诸郡。更始时入朝任御史大夫，后逃回天水，自称西州上将军，礼贤下士，名震西州。光武初年与之通好，遣子入侍；建武六年拒汉军于陇坻，向公孙述称臣。八年光武亲征，部众大溃，他逃往西城，九年春“**后汉书|病且饿，出城餐糗糒，恚愤而死**”。'],
  公孙述: ['子阳', '?–36', '字子阳，扶风茂陵人，哀帝时以父任为郎，王莽时为导江卒正（蜀郡太守），以能干著称。更始立后，他击灭入蜀虏掠的宗成等，自立为蜀王，都成都。建武元年四月称帝，“**后汉书|自立为天子，号成家，色尚白**”，据有巴蜀，北据汉中，东守江关，与光武相持十二年，曾派刺客先后刺杀来歙、岑彭。建武十二年吴汉攻破成都，他在城下决战时受伤，当夜死去，宗族被诛灭。'],
  邓绥: ['', '81–121', '护羌校尉邓训之女、邓禹之孙女，六岁能读史书，十二岁通《诗》《论语》，家人号为“诸生”。永元八年入宫为贵人，“**后汉书|恭肃小心，动有法度**”，十四年阴后被废后立为皇后。和帝崩后先后迎立殇帝、安帝，以太后临朝十六年，减省宫中用度，从班昭受经书，兼通天文算数。其间水旱连年、羌乱蔓延，她勤于赈恤，天下赖以粗安，兄邓骘等也能谦退。建光元年崩，谥和熹皇后，死后不久邓氏被安帝诛废。'],
  蔡伦: ['敬仲', '?–121', '字敬仲，桂阳人。永平末入宫，章帝时为小黄门，曾受窦皇后讽旨，诬陷太子刘庆之母宋贵人。和帝即位后为中常侍，参与帷幄，“**后汉书|数犯严颜，匡弼得失**”，后加位尚方令，监造器械精工坚密。他“**后汉书|用树肤、麻头及敝布、鱼网以为纸**”，元兴元年奏上，天下称为“蔡侯纸”。邓太后时封龙亭侯，为长乐太仆，监典东观校书。安帝亲政后追究宋贵人旧案，令他自赴廷尉，他耻于受辱，沐浴整衣冠，饮药而死。'],
  班昭: ['惠班', '?–?', '一名姬，字惠班，班彪之女，班固、班超之妹，博学高才，嫁同郡曹世叔，早寡。班固死时《汉书》八表与《天文志》未成，和帝诏她到东观藏书阁续成，又召入宫中为皇后、诸贵人之师，号“曹大家”。永元十二年上书为兄班超求归，和帝感动，召班超回国。邓太后临朝后，她参与政事，太后之兄邓骘以母丧请辞，太后问她，她劝太后许之。晚年作《女诫》七篇，年七十余卒，太后素服举哀。'],
  任尚: ['', '?–118', '东汉将领，早年为窦宪的司马，永元三年随耿夔在金微山大破北单于。永元十四年接替班超为西域都护，班超告诫他塞外吏士本非孝子顺孙，“**后汉书|水清无大鱼**”，宜宽小过、总大纲，他以为平平。到任后严急失众，延平元年西域诸国反叛，被围于疏勒，征还。安帝时羌乱，他为中郎将、征西校尉，屯兵三辅，元初四年用虞诩之策击破先零羌，杀其首领零昌、狼莫。次年因虚报战功、盗取军资千万以上，被槛车征还，弃市。'],
  李膺: ['元礼', '110–169', '字元礼，颍川襄城人，性简亢，唯以荀淑、陈寔为师友。历任青州刺史、渔阳太守、度辽将军，鲜卑畏其威名。桓帝时为河南尹、司隶校尉，中常侍张让之弟张朔贪残，逃入张让家合柱中，他破柱取出诛之，宦官皆鞠躬屏气。士人得其接纳称为“登龙门”，太学生称“**后汉书|天下模楷李元礼**”。延熹九年被诬结党下狱，次年赦归，禁锢终身。灵帝初复起为长乐少府，建宁二年再兴党狱，他说“事不辞难，罪不逃刑”，自诣诏狱，考死狱中。'],
  陈蕃: ['仲举', '?–168', '字仲举，汝南平舆人，十五岁时独居一室，庭宇芜秽，父友薛勤问他为何不洒扫待客，他说大丈夫处世当扫除天下，安事一室。历任乐安太守、尚书令、太尉，刚直敢言，屡谏桓帝宠任宦官，太学生称“**后汉书|不畏强御陈仲举**”。延熹九年拒绝签署逮捕党人的诏书，被免官。灵帝即位后以太傅与大将军窦武共录尚书事，谋诛宦官，事泄，七十余岁的他率官属诸生八十余人拔刃突入承明门，被王甫所擒，当日遇害。'],
  窦武: ['游平', '?–168', '字游平，扶风平陵人，窦融玄孙，少以经行著称，教授于大泽中，名显关西。延熹八年长女窦妙立为桓帝皇后，他拜城门校尉，封槐里侯，所得两宫赏赐悉散与太学诸生。党锢之祸时上表力请，党人得以赦归田里。桓帝崩后与女儿定策迎立灵帝，为大将军，与太傅陈蕃同心辅政，起用李膺等党人，谋诛宦官曹节、王甫，事泄，宦官矫诏发兵，张奂不明真相率兵围攻，窦武兵溃自杀，宗族宾客姻属悉被诛。'],
  窦妙: ['', '?–172', '窦武长女，延熹八年邓皇后被废后立为桓帝皇后，桓帝宠幸田圣等采女，她很少被召幸。永康元年桓帝崩，她以皇太后临朝，与父亲窦武定策迎立灵帝，桓帝灵柩尚在前殿，她便杀了田圣。建宁元年窦武、陈蕃谋诛宦官，事泄，曹节等劫持太后，夺其玺绶，窦氏被诛，她被迁居南宫云台。熹平元年其母死，她感疾而崩，宦官欲以贵人礼葬，廷尉陈球等力争，才与桓帝合葬，谥桓思皇后。'],
  范滂: ['孟博', '137–169', '字孟博，汝南征羌人，少厉清节，为州里所服。冀州饥荒、盗贼群起时，他为清诏使按察，“**后汉书|滂登车揽辔，慨然有澄清天下之志**”，守令望风解印绶而去。后为汝南太守宗资的功曹，严整疾恶。延熹九年党锢之祸被捕入黄门北寺狱，次年赦归，汝南、南阳士大夫迎者车数千辆。建宁二年再捕党人，他自诣县狱，县令郭揖解印绶要与他同逃，他不肯，与母诀别，母亲说能与李膺、杜密齐名，死亦何恨，遂死狱中，年三十三。'],
  段颎: ['纪明', '?–179', '字纪明，武威姑臧人，西域都护段会宗的从曾孙，少习弓马，好游侠，长大后折节好古学。桓帝时为辽东属国都尉，破鲜卑，又平泰山公孙举。延熹二年起为护羌校尉，与西羌、东羌转战十余年，主张以武力剿灭，前后一百八十战，斩首三万八千余级，建宁二年平定东羌，封新丰县侯。他依附宦官王甫，曾捕系太学生千余人，官至太尉。光和二年王甫被诛，他受牵连下狱，饮鸩而死。'],
  张奂: ['然明', '104–181', '字然明，敦煌渊泉人，少游三辅，师事太尉朱宠，删减《牟氏章句》。桓帝时为安定属国都尉，以二百人击退南匈奴与东羌，羌豪献马献金，他以酒酹地，悉数退还。延熹年间为使匈奴中郎将、度辽将军，招抚南匈奴、乌桓，击退鲜卑檀石槐，又与段颎同平羌乱。建宁元年刚回京师，被宦官矫诏利用，率兵围攻窦武，事后深以为恨，上书为陈蕃、窦武鸣冤，被宦官排挤，禁锢归田，闭门授徒，光和四年卒。'],
  檀石槐: ['', '137–181', '鲜卑首领。其母说是白天仰视时冰雹落入口中而怀孕，父亲投鹿侯不信，将他弃掉，母亲托娘家收养。十四五岁时单骑追回被抢的牛羊，被推为大人。他立庭于弹汗山歠仇水上，“**后汉书|南抄缘边，北拒丁零，东却夫余，西击乌孙，尽据匈奴故地**”，东西万四千余里，分为东、中、西三部。桓帝想封他为王、与之和亲，他拒不接受，连年寇掠幽、并、凉三州。熹平六年大破夏育等三路汉军。光和四年死，年四十五，鲜卑联盟随即瓦解。'],
  祭遵: ['弟孙', '?–33', '字弟孙，颍川颍阳人，少好经书，家富而恭俭。刘秀破昆阳后经过颍阳，以他为门下史，从征河北任军市令，刘秀家中的小儿犯法，他依法格杀，刘秀反而以他为刺奸将军，告诫诸将“当备祭遵”。建武初拜征虏将军，封颍阳侯，平定张满等，征陇时镇守汧县，与隗嚣相持。他廉约小心，克己奉公，赏赐尽分士卒，家无私财，建武九年死于军中，光武亲临送葬，痛哭不已。云台二十八将之一。'],
  寇恂: ['子翼', '?–36', '字子翼，上谷昌平人，世为著姓。王郎起兵时他劝上谷太守耿况归附刘秀，刘秀北征燕、代时拜他为河内太守，行大将军事，说“河内完富，吾将因是而起”，他坚守转运，伐淇园之竹为箭百余万，又击退朱鲔的进攻，保障前线军需。后任颍川太守、执金吾，曾与贾复结怨，以大局为重主动避让。光武亲征隗嚣时，他斩隗嚣部将的使者皇甫文，迫使高峻投降。云台二十八将之一。'],
  贾复: ['君文', '?–55', '字君文，南阳冠军人，少好学，习《尚书》。王莽末聚众数百，后归附刘秀，任破虏将军督盗贼。他每战先登，在射犬说“先破之，然后食耳”，在真定与五校交战时身受重伤，光武大惊说“失吾名将”，许诺与他结为儿女亲家。光武即位后拜执金吾，封胶东侯，从征多有战功。他知光武欲偃武修文，与邓禹一同交出兵权，专心儒学。云台二十八将之一。'],
  甄丰: ['长伯', '?–10', '字长伯，平帝时任左将军、少傅，与王舜、刘歆等同为王莽的心腹，参与谋划安汉公、宰衡等尊号。新朝建立，封广新公、更始将军，但王莽对他心存猜忌。始建国二年，他的儿子甄寻伪造符命，先说甄丰应为右伯，又说平帝的皇后应嫁给自己，王莽大怒收捕，甄丰自杀，甄寻逃亡后被擒，牵连刘歆的儿子及公卿列侯数百人。'],
  // ---------- 汉末三国 ----------
  於夫罗: ['', '?–195', '南匈奴单于羌渠之子，中平年间率兵助汉讨张纯。父亲被国人与休屠各胡所杀后，他继立为单于，国人又叛立须卜骨都侯，他只得到洛阳诉冤。适逢灵帝崩，天下大乱，他率数千骑与白波军合兵寇掠河内，后依附袁绍，又劫持张杨，追随袁术与曹操交战，屡战失利，最终留居河东平阳，兴平二年死，弟呼厨泉继立。'],
  刘焉: ['君郎', '?–194', '字君郎，江夏竟陵人，汉鲁恭王之后，历任南阳太守、宗正、太常。灵帝末见王室多故，建议改刺史为州牧、选清名重臣出镇，本想求为交趾牧避乱，听说益州有天子气，改求益州牧。入蜀后徙治绵竹，抚纳流亡，派张鲁据汉中断绝谷阁，诛杀州中豪强，造天子乘舆车具千余乘，阴图自立。兴平元年长子刘范等在长安谋诛李傕失败被杀，绵竹又遭天火，他迁居成都，忧愤发背疽而死，子刘璋继任。'],
  曹操: ['孟德', '155–220', '字孟德，沛国谯人，中常侍曹腾的养孙，父曹嵩官至太尉。少机警，有权数，任侠放荡，不治行业，汝南许劭称他为“治世之能臣，乱世之奸雄”。二十岁举孝廉，为洛阳北部尉，造五色棒，蹇硕之叔违禁夜行，即被棒杀。中平元年为骑都尉，在长社与皇甫嵩、朱儁合兵大破颍川黄巾，迁济南相，奏免贪吏八人。中平五年为西园典军校尉。董卓入京后，他变易姓名东归，散家财起兵讨卓，此后统一北方，奠定曹魏基业，建安二十五年卒。'],
  袁绍: ['本初', '?–202', '字本初，汝南汝阳人，袁安玄孙，袁氏四世五公，他虽为庶出，而有姿貌威容，能折节下士，宾客辐辏。中平五年为西园中军校尉。灵帝崩后他劝何进尽诛宦官，召四方猛将入京，何进被杀后，他率兵入宫，尽杀宦官二千余人。董卓议废少帝，他横刀长揖而出，奔冀州，后被推为关东讨卓联军盟主。此后据有冀、青、幽、并四州，建安五年在官渡被曹操击败，两年后病死。'],
  董卓: ['仲颖', '?–192', '字仲颖，陇西临洮人，性粗猛有谋，少尝游羌中，尽与豪帅相结，膂力过人，双带两鞬，左右驰射。桓帝时为羽林郎，随张奂击汉阳叛羌，屡立战功。黄巾起时代卢植讨张角，无功被免；中平二年随张温讨凉州叛军，诸军皆败，唯他全军而还。中平五年为前将军，与皇甫嵩救陈仓。何进召外兵入京，他率兵到洛阳，吞并何氏部曲，废少帝，立献帝，专擅朝政，后焚洛阳、迁都长安，初平三年被王允、吕布所杀。'],
  汉献帝: ['', '181–234', '名协，灵帝之子，母王美人生他后被何皇后鸩杀，由董太后抚养，号“董侯”。初封渤海王，后徙陈留王。中平六年随少帝被张让劫持至小平津，见董卓时说话从容，将祸乱始末讲述清楚，董卓以为贤，九月废少帝，立九岁的他为帝。此后先后受制于董卓、李傕郭汜，建安元年被曹操迎至许都，名为天子而实为傀儡。延康元年禅位于曹丕，封山阳公，青龙二年卒。'],
  孙坚: ['文台', '155–191', '字文台，吴郡富春人，相传为孙武之后。十七岁时与父亲乘船至钱唐，遇海贼劫掠商旅，他提刀上岸，指挥若招呼兵众，贼惊散，由此知名。熹平元年以郡司马募兵千余人，助州郡破会稽许生之乱。中平元年为朱儁的佐军司马，在宛城率先登城，以功拜别部司马；后随张温讨边章、韩遂。中平四年任长沙太守，平区星之乱，封乌程侯。后起兵讨董卓，攻入洛阳，初平二年进攻刘表时在岘山中箭而死。'],
  公孙瓒: ['伯珪', '?–199', '字伯珪，辽西令支人，家世二千石，因母亲出身卑贱，只做郡中小吏，貌美声洪，言事辩慧，受太守赏识，娶其女。曾与刘备同学于卢植。中平年间以骑都尉讨张纯，屡破乌桓，常乘白马，号“白马长史”，乌桓相告避之。后与幽州牧刘虞不和，初平四年击杀刘虞，据有幽州，筑易京自守。与袁绍连年交战，建安四年易京被袁绍攻破，他自焚而死。'],
  刘虞: ['伯安', '?–193', '字伯安，东海郯人，光武之子东海恭王刘彊的后代。初举孝廉，为幽州刺史时民夷感其德化，鲜卑、乌桓、夫余、濊貊皆随时朝贡。中平五年张纯、张举反叛，朝廷以他为幽州牧，他遣使晓谕乌桓，悬赏购斩张纯，北州乃定。他为政宽仁，劝督农植，开上谷胡市，流民百余万口归之。初平中袁绍等欲立他为帝，他坚辞不受。后与公孙瓒不和，兴兵攻之，兵败被擒，初平四年被公孙瓒所杀。'],
  关羽: ['云长', '?–220', '字云长，本字长生，河东解人，亡命奔涿郡，与张飞随刘备起兵，“**三国志|先主与二人寝则同床，恩若兄弟**”。建安五年被曹操所擒，拜偏将军，在白马“**三国志|策马刺良于万众之中**”，封汉寿亭侯，随即尽封所赐，奔归刘备。赤壁战后为襄阳太守，刘备入蜀后董督荆州。建安二十四年北攻樊城，水淹于禁七军，威震华夏，孙权遣吕蒙袭取江陵，他退走麦城，被吴军擒杀。'],
  张飞: ['益德', '?–221', '字益德，涿郡人，少与关羽俱事刘备，关羽年长数岁，他以兄事之。建安十三年刘备在当阳长坂被曹军追及，他率二十骑拒后，据水断桥，瞋目横矛说“**三国志|身是张益德也，可来共决死！**”曹军无敢近者。后随诸葛亮入蜀，义释严颜，又在瓦口大破张郃，刘备称帝后为车骑将军、司隶校尉。他敬爱君子而不恤小人，常鞭挞健儿，章武元年将伐吴时被部将张达、范强所杀。'],
  孙权: ['仲谋', '182–252', '字仲谋，孙坚次子，孙策之弟，形貌奇伟。建安五年孙策遇刺，十九岁的他继位，任用张昭、周瑜、鲁肃，招延俊秀。建安十三年与刘备联合，在赤壁大破曹操；后遣吕蒙袭杀关羽，夺取荆州，又以陆逊在夷陵大败刘备。黄武元年受魏封为吴王后与魏绝交，黄龙元年在武昌称帝，迁都建业。晚年多疑，二宫之争中废太子孙和、赐死孙霸，太元二年卒，年七十一，在位五十余年。'],
  周瑜: ['公瑾', '175–210', '字公瑾，庐江舒人，长壮有姿貌，与孙策同年，推结分好，升堂拜母。孙策渡江时率兵迎助，攻破刘繇，又取皖城，二人分娶桥公二女。孙策死后他与张昭共辅孙权，以中护军统兵。建安十三年曹操南下，群臣多劝迎降，他力主抗曹，与刘备合兵在赤壁用黄盖火攻大破曹军，又攻取江陵。正欲西取益州，建安十五年病逝于巴丘，年三十六。他精通音乐，时人谣曰“**三国志|曲有误，周郎顾**”。'],
  张昭: ['子布', '156–236', '字子布，彭城人，少好学，善隶书，博览众书。汉末避乱扬州，孙策创业时任为长史、抚军中郎将，文武之事一以委之。孙策临终托以孙权，他率群僚立而辅之，安定人心。建安十三年曹操南下，他主张迎降，为孙权所不悦。孙权称帝后，他以老病归还官位，每次朝见辞气壮厉，义形于色，孙权多次与他争执，甚至土塞其门。嘉禾五年卒，年八十一，著有《春秋左氏传解》《论语注》。'],
  张郃: ['儁乂', '?–231', '字儁乂，河间鄚人，黄巾起时应募讨贼，后归袁绍，以破公孙瓒有功为宁国中郎将。官渡之战时劝袁绍救乌巢，袁绍不从，淳于琼兵败后他与高览投降曹操，曹操比之为微子去殷、韩信归汉。此后从征乌桓、马超、张鲁，与夏侯渊镇守汉中，夏侯渊战死后被推为主帅，稳住阵脚。太和二年在街亭大破马谡，太和五年追击诸葛亮至木门，中箭而死。'],
  张辽: ['文远', '169–222', '字文远，雁门马邑人，本姓聂，是马邑之谋聂壹的后代。少为郡吏，先后属丁原、何进、董卓、吕布。建安三年吕布败亡，他率众降曹操，拜中郎将，此后从征袁谭、袁尚，在白狼山大破乌桓，斩蹋顿。建安二十年孙权率十万众围合肥，他夜募敢死之士八百人，次日被甲持戟，先登陷阵，“**三国志|冲垒入，至权麾下**”，孙权惊走登冢，此后围城十余日不克，撤退时又在逍遥津几乎擒获孙权，威震江东。黄初三年病卒于江都。'],
  荀彧: ['文若', '163–212', '字文若，颍川颍阴人，祖父荀淑、父荀绲皆有名德，南阳何颙见而称他是“王佐才”。他初投袁绍，知其终不能成大事，初平二年转投曹操，曹操大喜说“吾之子房也”。曹操征徐州时，他与程昱固守鄄城、范、东阿三城，保住了兖州根本。他力劝曹操迎献帝都许，“**三国志|奉主上以从民望**”，又先后推荐荀攸、郭嘉、钟繇、陈群等，官渡之战时劝曹操坚持。后来反对曹操进爵魏公，建安十七年忧卒于寿春。'],
  郭嘉: ['奉孝', '170–207', '字奉孝，颍川阳翟人，少有远量，汉末天下将乱，他不与俗接，秘密交结英杰。初投袁绍，认为袁绍“多端寡要，好谋无决”，离去。经荀彧推荐见曹操，曹操说“使孤成大业者，必此人也”，他也说“真吾主也”。此后从征吕布、刘备，料定孙策将死于匹夫之手、袁绍性迟而多疑，屡言屡中。官渡后又献计平定河北，随曹操北征乌桓，因水土不服病死，年三十八，曹操在赤壁战败后叹道“郭奉孝在，不使孤至此”。'],
  贾诩: ['文和', '147–223', '字文和，武威姑臧人，少时汉阳阎忠称他有“良、平之奇”。董卓死后，他劝李傕、郭汜率众西攻长安，致使关中大乱，裴注引裴松之评为“祸烈”。后依段煨，又投张绣为谋主，曾两次料定曹操追退之胜败。建安四年劝张绣归曹，官渡之战劝曹操决战，赤壁前劝曹操勿急于东下，潼关之战献离间马超、韩遂之计。曹丕立为太子时他有功，曹丕即位后为太尉，年七十七卒，算无遗策，以明哲保身著称。'],
  刘表: ['景升', '142–208', '字景升，山阳高平人，鲁恭王之后，身长八尺余，姿貌甚伟，少知名，号为“八俊”。初平元年接任荆州刺史，“**三国志|单马入宜城**”，与蒯良、蒯越、蔡瑁合谋诱杀宗贼，平定江南，移治襄阳，据荆州八郡，地方数千里，带甲十余万。他起立学校，博求儒术，关西、兖、豫学士归之者数千人，但不能大有作为，袁、曹相争时持中立。射杀孙坚，收容刘备。建安十三年曹操南征时病死，其子刘琮降曹。'],
  刘备: ['玄德', '161–223', '字玄德，涿郡涿县人，中山靖王刘胜之后，少孤，与母贩履织席为业，好交结豪侠，与关羽、张飞恩若兄弟。黄巾起时以军功为安喜尉，后依公孙瓒为平原相，又救陶谦，领徐州，被吕布袭夺，投曹操，曹操说“**三国志|今天下英雄，唯使君与操耳**”。后来参与衣带诏之谋，袭杀车胄，被曹操击败，投袁绍、刘表，三顾诸葛亮，赤壁战后取荆州、益州、汉中，章武元年称帝，夷陵之败后病逝于白帝城。'],
  韩遂: ['文约', '?–215', '本名约，字文约，金城人，与边章同为凉州名士，曾到京师见何进，劝诛宦官。中平元年被湟中义从胡北宫伯玉等劫持，与边章专任军政，以诛宦官为名，攻杀金城太守，侵逼三辅。后来他杀了边章、北宫伯玉，拥兵十余万，与马腾、王国连兵，凉州刺史耿鄙、汉阳太守傅燮先后败死。此后割据凉州三十余年，时附时叛，建安十六年与马超联军反曹操，在潼关大败，后被部下所杀，年七十余。'],
  诸葛亮: ['孔明', '181–234', '字孔明，琅邪阳都人，早孤，随叔父诸葛玄避乱荆州，躬耕陇亩，好为《梁父吟》，每自比于管仲、乐毅，号为卧龙。建安十二年刘备三顾草庐，他提出跨有荆益、联吴抗曹的隆中对；赤壁前出使江东促成孙刘联盟，此后辅佐刘备取荆南、定益州。刘备称帝后为丞相，白帝城受托孤，辅佐后主，南征平定南中，五次北伐，自称“**三国志|鞠躬尽力，死而后已**”（裴注引《汉晋春秋》所载后出师表），建兴十二年病卒于五丈原军中，年五十四。'],
  赵云: ['子龙', '?–229', '字子龙，常山真定人，本属公孙瓒，后归刘备，为主骑。建安十三年当阳长坂之役，“**三国志|云身抱弱子，即后主也，保护甘夫人，即后主母也，皆得免难**”。后随诸葛亮入蜀，平定江州、江阳，为翊军将军。汉中之战中救回黄忠，大开营门，偃旗息鼓，曹军疑有伏兵而退，刘备次日视察战场，说“**三国志|子龙一身都是胆也**”（裴注引《云别传》）。建兴六年随诸葛亮北伐，以疑兵出箕谷，兵败而不至大损，次年卒。'],
  马超: ['孟起', '176–222', '字孟起，扶风茂陵人，马腾之子，骁勇过人，为羌胡所敬。马腾入朝后他领其部众，建安十六年与韩遂等关中十部起兵，与曹操相持于潼关、渭南，被离间击败，退回凉州，在冀城杀凉州刺史韦康，又被杨阜等起兵击败，投奔张鲁。其父马腾与兄弟在邺城因他反叛被曹操诛杀。建安十九年从汉中投刘备，屯成都城北，城中震怖，刘璋遂降。刘备称汉中王时为左将军，称帝后为骠骑将军、凉州牧，章武二年卒，年四十七。'],
  魏延: ['文长', '?–234', '字文长，义阳人，以部曲随刘备入蜀，数有战功。刘备得汉中，众人以为必用张飞镇守，刘备却拔擢他为汉中太守、镇远将军，他说“若曹操举天下而来，请为大王拒之；偏将十万之众至，请为大王吞之”。诸葛亮北伐时为前锋，屡请率兵万人别道出子午谷与诸葛亮会于潼关，诸葛亮不许，他常说诸葛亮怯。建兴八年大破魏将郭淮。诸葛亮死后，他与杨仪不和，烧绝阁道，南攻杨仪，兵众散去，被马岱追斩，夷三族。'],
  陆逊: ['伯言', '183–245', '字伯言，吴郡吴县人，世为江东大族，娶孙策之女。二十一岁入孙权幕府，平定山越，得精兵数万。建安二十四年代吕蒙屯陆口，以谦辞麻痹关羽，助吕蒙袭取荆州，又别取宜都。黄武元年以大都督拒刘备，坚守不战，待蜀军疲敝，在夷陵火烧连营，大破蜀军；黄武七年在石亭大破曹休。赤乌七年代顾雍为丞相，因卷入太子孙和与鲁王孙霸之争，屡被孙权遣使责问，愤恚而卒，年六十三。'],
  曹丕: ['子桓', '187–226', '字子桓，曹操次子，母卞夫人，八岁能属文，善骑射，好击剑，博贯古今经传诸子百家之书。建安十六年为五官中郎将、副丞相，与弟曹植争立太子多年，二十二年被立为太子。曹操死后继位为魏王，延康元年改行九品官人法，同年十月受汉禅即皇帝位，改元黄初，是为魏文帝。在位期间三次伐吴无功，著有《典论》，其中《论文》篇是中国最早的文学批评专论。黄初七年病卒，年四十。'],
  司马懿: ['仲达', '179–251', '字仲达，河内温县人，少有奇节，聪朗多大略。建安年间被曹操强征入仕，后辅佐曹丕为太子中庶子，曹丕临终受遗诏辅政。太和二年八日兼行擒斩孟达，此后长期在关中抵御诸葛亮，坚守不战，时有“**三国志|死诸葛走生仲达**”之谚（裴注引《汉晋春秋》）。景初二年平定辽东公孙渊。明帝临终与曹爽同受托孤，被夺权后称病不出，嘉平元年发动高平陵之变诛灭曹爽，又平定王凌之叛，同年卒，年七十三，晋朝建立后追尊为宣帝。'],
  司马师: ['子元', '208–255', '字子元，司马懿长子，雅有风采，沈毅多大略，少与夏侯玄、何晏齐名。高平陵之变时预先暗养死士三千，事发之日指挥若定。司马懿死后以大将军辅政，嘉平四年东兴之役败于诸葛恪，引咎自责，次年在合肥新城挫败吴军。正元元年诛李丰、夏侯玄，废魏帝曹芳，立高贵乡公曹髦。次年毌丘俭、文钦在淮南起兵，他带眼疾亲征，平定叛乱，但被文钦之子文鸯夜袭惊得目疾加剧，回到许昌病死，年四十八，晋追尊为景帝。'],
  司马昭: ['子上', '211–265', '字子上，司马懿次子，司马师之弟，随父征伐，参与高平陵之变。正元二年司马师死后继为大将军，专擅朝政，甘露二年至三年平定诸葛诞的淮南之叛。甘露五年魏帝曹髦不甘为傀儡，说“**三国志|司马昭之心，路人所知也**”（裴注引《汉晋春秋》），率宿卫进攻，被贾充指使成济刺死，他改立曹奂。景元四年派钟会、邓艾伐蜀，灭蜀汉，进爵晋王，咸熙二年卒，年五十五，其子司马炎随即代魏建晋，追尊他为文帝。'],
  毌丘俭: ['仲恭', '?–255', '字仲恭，河东闻喜人，父毌丘兴为武威太守。魏明帝在东宫时他为文学掾，深受亲信。青龙年间为幽州刺史，景初元年奉命征讨公孙渊，遇大雨不克，次年随司马懿平辽东。正始年间两次征讨高句丽，“**三国志|束马县车，以登丸都**”，刻石纪功，又追至肃慎南界。后任镇东将军，都督扬州。他与夏侯玄、李丰交好，二人被诛、曹芳被废后，正元二年与扬州刺史文钦在寿春起兵讨司马师，兵败逃走，在慎县被民兵射杀，夷三族。'],
  诸葛诞: ['公休', '?–258', '字公休，琅邪阳都人，诸葛亮的族弟，与夏侯玄、邓飏等相善，因浮华之名被魏明帝罢官。正始年间复起，为扬州刺史。嘉平四年与胡遵攻东兴，被吴将丁奉大败。毌丘俭起兵后他率先进据寿春，接替镇守淮南，厚养死士。因王凌、毌丘俭相继被夷族，心不自安，甘露二年被征为司空，遂起兵反，联合东吴，坚守寿春近一年。次年二月城破，他突围被斩，麾下数百人宁死不降，皆曰“**三国志|为诸葛公死，不恨**”。'],
  刘禅: ['公嗣', '207–271', '字公嗣，小字阿斗，刘备之子，母甘夫人，长坂之役被赵云怀抱得免。章武三年十七岁即位，政事无巨细咸决于诸葛亮。诸葛亮死后先后任用蒋琬、费祎，与民休息；费祎死后姜维连年北伐，他又宠信宦官黄皓，朝政日坏。景耀六年魏将邓艾偷渡阴平直抵成都，他采纳谯周之议出城投降，蜀汉亡。迁居洛阳，封安乐县公，司马昭问他是否思蜀，他说“**三国志|此间乐，不思蜀**”（裴注引《汉晋春秋》）。泰始七年卒，年六十五。'],
  姜维: ['伯约', '202–264', '字伯约，天水冀县人，少孤，好郑玄经学。建兴六年诸葛亮第一次北伐时归蜀，诸葛亮称他“**三国志|凉州上士也**”，深加器重。诸葛亮死后受蒋琬、费祎节制，费祎死后连年北伐，延熙十八年在洮西大破魏雍州刺史王经，次年在段谷被邓艾所败，蜀中虚耗。景耀六年魏军伐蜀，他退守剑阁拒钟会，邓艾偷渡阴平，后主投降，他奉敕降钟会，又劝钟会反叛司马昭，欲借机复蜀，事败与钟会同被乱兵所杀，年六十三。'],
  孙亮: ['子明', '243–260', '字子明，孙权少子，母潘夫人。二宫之争后，赤乌十三年被立为太子，太元二年十岁即位，诸葛恪辅政。诸葛恪被孙峻诛杀后，孙峻、孙綝兄弟相继专权。他十六岁亲政，常出题考问孙綝，又在苑中训练少年兵，太平三年与全尚等密谋诛孙綝，事泄，被孙綝废为会稽王，后又被贬为候官侯，在赴封地途中自杀，一说被毒杀，年十八。'],
  孙峻: ['子远', '219–256', '字子远，孙坚之弟孙静的曾孙，少便弓马，精果胆决，孙权末年为武卫都尉，与诸葛恪等同受托孤。建兴二年诸葛恪攻新城失利，民怨沸腾，他与孙亮密谋，在宫中设宴伏兵杀诸葛恪，自任丞相、大将军，督中外诸军事，又赐死废太子孙和，与孙权之女全公主私通，骄矜淫暴，多所刑杀。五凤二年率军袭寿春无功，次年准备伐魏时梦见被诸葛恪所击，惊惧病死，年三十八，以后事托堂弟孙綝。'],
  丁奉: ['承渊', '?–271', '字承渊，庐江安丰人，少以骁勇为小将，随甘宁、陆逊、潘璋征伐，屡次斩将搴旗。建兴元年诸葛恪在东兴抗魏，他率三千人冒雪进发，令士卒脱去铠甲，持短兵登堤，大破魏军，以功迁冠军将军。孙休即位后，他与张布合谋，在腊会上擒斩专权的孙綝。孙皓时为右大司马、左军师，仍屡次率军伐晋，建衡三年卒，后因旧事被孙皓迁其家属于临川。'],
  曹芳: ['兰卿', '232–274', '字兰卿，魏明帝的养子，来历不明。景初三年明帝临终立为太子，八岁即位，由曹爽、司马懿辅政。嘉平元年高平陵之变后，政事尽归司马氏。嘉平六年中书令李丰、夏侯玄等谋以夏侯玄代司马师辅政，事泄被诛，同年九月司马师以太后之令，指责曹芳荒淫无度、亵近倡优，将他废为齐王，迁居河内。西晋代魏后封为邵陵县公，泰始十年卒，年四十三。'],
  张鲁: ['公祺', '?–216', '字公祺，沛国丰人。祖父张陵在蜀中鹄鸣山学道，造作道书，受道者出米五斗，号五斗米道，父张衡传其业，母亲以鬼道常往来刘焉家。刘焉以他为督义司马，派他据汉中断绝谷阁；刘焉死后，他与刘璋反目，割据汉中近三十年。他不置长吏，以祭酒治民，设义舍置米肉供行旅取用，“**三国志|犯法者，三原，然后乃行刑**”，民夷便乐。建安二十年曹操西征，他封存府库逃往巴中，十一月出降，拜镇南将军，封阆中侯，五子皆封列侯，次年去世。'],
  士燮: ['威彦', '137–226', '字威彦，苍梧广信人，少游学京师，师事刘陶，治《左氏春秋》。汉末为交趾太守，交州刺史朱符被杀后，他表弟弟士壹、士䵋、士武分领合浦、九真、南海，一家雄长交州，出入鸣钟磬，备具威仪。他宽厚谦虚，礼贤下士，中原士人避难者以百数。建安十五年孙权派步骘为交州刺史，“**三国志|燮率兄弟奉承节度**”，遣子入质，每年贡献珍奇，又诱导益州豪强雍闿归附孙权。在郡四十余年，黄武五年卒，年九十；其子士徽据交趾抗命，被吕岱诛灭。'],
  荀攸: ['公达', '157–214', '字公达，颍川颍阴人，荀彧之侄而年长于荀彧。何进时为黄门侍郎，曾与郑泰等谋刺董卓，事泄下狱，董卓死后得免。曹操迎天子后召他为军师，从征张绣、吕布，决泗、沂之水灌下邳擒吕布；官渡之战中献声东击西之计斩颜良、文丑，又力劝曹操亲袭乌巢。他深密有智防，前后为曹操出奇策十二，曹操说“公达外愚内智，外怯内勇”。魏国建立后任尚书令，从征孙权途中病卒。'],
  钟繇: ['元常', '151–230', '字元常，颍川长社人，以孝廉为尚书郎。献帝在长安时，他说服李傕、郭汜允许曹操的使者通行，后协助献帝东归。曹操以他为司隶校尉，持节督关中诸军，招抚马腾、韩遂，使之遣子入质；官渡之战时送马二千余匹给军，曹操比之为萧何。魏国建立后任相国，曹丕时为太尉，明帝时为太傅，人称钟太傅。他精于书法，尤善楷书，与王羲之并称“钟王”。其子钟会后来灭蜀。'],
  乐进: ['文谦', '?–218', '字文谦，阳平卫国人，身材短小，以胆烈从曹操，每战先登。从征吕布、张绣、袁绍，官渡之战时随曹操攻破乌巢，斩淳于琼，又从攻邺城、平高干，以功拜折冲将军，与于禁、张辽并为名将。合肥之战时与张辽、李典同守合肥，大败孙权。后屯襄阳，击关羽、苏非等，建安二十三年卒。'],
  徐晃: ['公明', '?–227', '字公明，河东杨人，原是杨奉的部将，劝杨奉归附曹操，后随曹操征伐。官渡之战时烧毁袁军运粮车；潼关之战时率先渡蒲阪津占据河西，为大军开路。关羽围樊城时，他率军救援，长驱直入关羽的十重长围，大破关羽，解樊城之围，曹操赞他“将军之功，逾孙武、穰苴”。他治军严整，为人俭约谨慎，曹丕时任右将军，封阳平侯。'],
  王朗: ['景兴', '?–228', '字景兴，东海郯人，以通经拜郎中，陶谦任他为会稽太守。孙策渡江后来攻，他兵败浮海逃往东冶，最终投降，孙策因他是儒雅之士不加害。后被曹操征召，任谏议大夫、魏郡太守、大理等职，执法宽恕。曹丕代汉时率群臣劝进，任司空，明帝时为司徒，屡次上疏劝明帝节俭、减省徭役，著有《易》《春秋》《孝经》等传注。其孙女王元姬是晋武帝之母。'],
  蒋济: ['子通', '?–249', '字子通，楚国平阿人，任扬州别驾，赤壁之战后孙权围合肥，他伪造援军书信使孙权退兵。关羽水淹七军、威震华夏时，他与司马懿劝曹操联络孙权，许以江南，袭关羽后路，关羽因此败亡。明帝时任护军将军，齐王时为太尉，高平陵之变时随司马懿屯洛水浮桥，写信劝曹爽投降，保证只是免官，曹爽被诛后他自觉失信，发病而死。'],
  张燕: ['', '?–?', '常山真定人，本姓褚，黄巾起时聚众为盗，与博陵张牛角合军，张牛角中箭将死，令众人奉褚燕为帅，他于是改姓张。他剽悍敏捷，号称“飞燕”，部众号称百万，称为黑山军，盘踞常山、中山、上党一带山谷。朝廷无力讨伐，任他为平难中郎将。后与公孙瓒联合对抗袁绍，易京之役时曾派兵往救。建安十年率众十余万降曹操，封安国亭侯。'],
  郭图: ['公则', '?–205', '字公则，颍川人，袁绍的谋士。官渡之战中他力主速战，建议派淳于琼守乌巢、张郃攻曹营，乌巢被烧后又谗毁张郃，张郃、高览因此降曹。袁绍死后他与辛评支持袁谭，挑起兄弟相争。建安十年南皮城破时与袁谭一同被杀。'],
  程普: ['德谋', '?–?', '字德谋，右北平土垠人，有容貌计略，善于应对。他随孙坚征讨黄巾、董卓，又随孙策渡江平定江东，多有战功，是孙氏三代的老将，众人尊称程公。赤壁之战时他与周瑜任左右督，大破曹军，又同攻南郡，周瑜死后领江夏太守。他起初自恃年长，屡次凌侮周瑜，周瑜折节容下，他后来感叹与周公瑾交往“若饮醇醪，不觉自醉”。'],
  吕范: ['子衡', '?–228', '字子衡，汝南细阳人，少为县吏，有容观姿貌，率私客百余人依附袁术，后随孙策渡江，平定江东，孙策委以财计之事，亲敬如兄弟。孙权时任都督，赤壁之战后为彭泽太守；黄武元年魏军三路伐吴，他督徐盛、全琮等在洞口抵御曹休，虽遇大风船覆，损失甚重，仍守住江防。黄武七年拜大司马，印绶未下而卒。'],
  朱然: ['义封', '182–249', '字义封，丹阳故鄣人，本姓施，朱治的外甥，过继为子，与孙权同学读书。他随吕蒙袭取荆州，与潘璋截断关羽归路；夷陵之战时与陆逊共破刘备。黄武元年曹真、夏侯尚等围江陵六个月，城中多肿病，能战者仅五千人，他坚守不动，魏军终退，由此名震敌国。后官至左大司马、右军师，身长不满七尺，气候分明，是吴国后期的柱石之将。'],
  潘璋: ['文珪', '?–234', '字文珪，东郡发干人，好酒，家贫，常赊酒欠账，说日后富贵再还。他随孙权多立战功，合肥之战撤退时斩杀退走者，阻止溃散。关羽败走麦城时，他与朱然截断关羽归路，部将马忠擒获关羽父子。夷陵之战时斩蜀将冯习等。为人粗猛，治军严整，但贪财奢侈，后官至右将军。'],
  滕胤: ['承嗣', '?–256', '字承嗣，北海剧人，伯父、父亲避乱江东，他二十岁娶孙权宗室之女，以才德著称，历任丹杨、吴郡、会稽太守。孙权临终时与诸葛恪等同受遗诏辅政，任太常；诸葛恪被孙峻所杀后，他为卫将军，与孙峻共掌朝政。孙峻死后，孙綝专权，他与吕据谋攻孙綝，事败，被孙綝所杀，夷三族。'],
  周襄王: ['', '?–前619', '名郑，周惠王之子。即位之初（前 651 年）派宰孔赐胙于葵丘之会上的齐桓公，承认其霸主地位。惠王宠爱王子带，他即位后王子带勾结戎狄攻周，前 636 年又与狄后私通，借狄师攻周，襄王出居于郑之氾地，向诸侯告难。晋文公听从狐偃“求诸侯莫如勤王”之策，次年出兵杀王子带，送襄王回到王城，襄王以阳樊、温、原、攒茅之田酬晋。前 632 年城濮之战后，他亲到践土慰劳晋文公，策命晋文公为侯伯。'],
  齐孝公: ['', '?–前633', '名昭，齐桓公之子，郑姬所生。桓公与管仲曾把他托付给宋襄公，立为太子。前 643 年桓公死后，五公子争立，易牙、竖刁立公子无亏，他出奔宋国。次年宋襄公率曹、卫、邾之师送他回国，齐人杀无亏，四公子之党与宋军战于甗，宋军败齐师，他即位为孝公。在位十年，曾伐鲁，被鲁展喜以“恃先王之命”劝退。'],
  宋襄公: ['', '?–前637', '名兹甫，宋桓公之子，以仁义自许。做太子时曾想把君位让给庶兄子鱼。前 642 年他率诸侯送齐孝公回国即位，此后欲继齐桓公称霸，执滕宣公，用鄫子于社。前 639 年盂之会被楚成王所执，后获释。前 638 年伐郑，楚救郑，两军战于泓水，他坚持楚军渡河未毕、未成列时不击，说君子“不重伤，不禽二毛”，结果大败，伤及大腿，次年伤重去世。'],
  张孟谈: ['', '?–?', '赵襄子的家臣，《史记》作“张孟同”。智伯率韩、魏围晋阳，引汾水灌城，城中悬釜而炊，易子而食，群臣都有外心。他夜里缒出城去见韩康子、魏桓子，说“唇亡则齿寒”，智伯灭赵之后必及韩、魏，二人遂约定倒戈。约定之日，赵氏决堤反灌智伯军营，韩魏从两翼夹击，大败智伯，三家分其地。事后他功成身退，辞去官职，耕于负亲之丘。'],
  韩王信: ['', '?–前196', '战国韩襄王的庶孙，身长八尺五寸。楚汉时随刘邦平定韩地，封韩王，荥阳之围中被项羽俘虏，后又逃回汉朝。汉初刘邦以其材武，把他徙封太原以北以备匈奴，都晋阳，后又自请迁到马邑。被冒顿围困时屡次遣使求和，被刘邦怀疑有二心，于是以马邑降匈奴，并引匈奴南下，导致白登之围。此后屡引匈奴入边，被汉将柴武斩于参合。'],
  王陵: ['', '?–前181', '沛县人，刘邦的同乡豪强，刘邦曾以兄事之。秦末自聚党数千人居南阳，后来归汉。项羽抓住他的母亲想招降他，王母对汉使说“善事汉王”，伏剑自杀。汉初封安国侯，继曹参为右丞相。吕后欲王诸吕，他以高祖“非刘氏而王，天下共击之”的白马之盟当面力争，陈平、周勃却表示赞同，他被免为帝太傅，从此杜门不朝，七年后去世。'],
  周勃: ['', '?–前169', '沛县人，以编织蚕箔、给丧事吹箫为生，随刘邦起兵，屡立战功，封绛侯。为人木强敦厚，不好文学，刘邦临终说“**史记|安刘氏者必勃也**”。吕后死后，他与陈平合谋，骗取吕禄的北军兵权，入军门令“为吕氏右袒，为刘氏左袒”，诛灭诸吕，迎立文帝，任右丞相。文帝问他一年断狱、钱谷出入几何，他汗流浃背答不上来，不久让位于陈平。晚年被诬谋反下狱，叹道“**史记|吾尝将百万军，然安知狱吏之贵乎**”。'],
  陆贾: ['', '?–?', '楚人，以客从刘邦定天下，有口辩，常出使诸侯。汉初出使南越，说服赵佗接受南越王印，称臣奉约，赵佗留他饮酒数月，赠千金。他常在刘邦面前称说《诗》《书》，刘邦骂他“乃公居马上而得之，安事诗书”，他答“**史记|居马上得之，宁可以马上治之乎**”，于是著《新语》十二篇。吕后时称病免官，劝陈平结交周勃，促成诛吕；文帝时再使南越，使赵佗去帝号。'],
  刘贾: ['', '?–前196', '刘邦的从兄。楚汉相争时随刘邦东击项羽，率兵渡淮，与彭越一同烧楚军积聚，又诱降楚大司马周殷，在垓下之战中合围项羽。韩信被废后，刘邦把楚地一分为二，封他为荆王，统辖淮东五十二城。英布反叛时东击荆国，刘贾兵败被杀，死于富陵。'],
  刘安: ['', '前179–前122', '淮南厉王刘长之子，袭封淮南王。“**史记|淮南王安为人好读书鼓琴，不喜弋猎狗马驰骋**”，招致宾客方术之士数千人，编成《淮南子》，武帝初年入朝献上《内篇》，武帝很喜爱。他对父亲被贬死于蜀道一直怀恨，暗中准备兵器、伪造玺印，与门客伍被等谋反。太子刘迁与郎中雷被比剑结仇，雷被逃到长安告发，伍被又自首，朝廷派宗正治罪，他自刭而死，淮南国除为九江郡。'],
  王邑: ['', '?–23', '王莽的堂弟，王商之子，嗣封成都侯，王莽代汉后任大司空。居摄二年翟义起兵时，他与孙建等领兵击败翟义。地皇四年与王寻发各州郡兵四十二万，号称百万，驱虎豹犀象之属助威，围攻昆阳，不听严尤之谏，被刘秀率三千敢死之士冲破中军，大败，与严尤、陈茂踏着死人渡水逃走，收拾残兵仅数千人回到洛阳。长安城破时护卫王莽到渐台，力战而死。'],
  马武: ['子张', '?–61', '字子张，南阳湖阳人，少时避仇客居江夏，参加绿林军，昆阳之战时随刘秀击王寻。后归光武，为捕虏将军，从征河北、陇右，屡建战功，封杨虚侯。他嗜酒豁达，常在光武面前直言评点诸将，光武以此为乐。建武二十七年与臧宫上书请乘北匈奴饥疫出击，被光武以“柔能制刚”拒绝。云台二十八将之一。'],
  彭宠: ['伯通', '?–29', '字伯通，南阳宛人，父亲彭宏在哀帝时为渔阳太守，因不附王莽被杀。他少为郡吏，更始时以偏将军行渔阳太守事。王郎起兵，他采纳吴汉之议，发突骑与上谷耿况共助刘秀，又转运粮草不绝，功劳甚大。光武即位后只得封侯，又与幽州牧朱浮不和，被征入朝，疑为朱浮所陷，建武二年起兵反，攻破蓟城，自立为燕王，北结匈奴。五年春在斋室中被苍头子密等缚于床上，斩首投汉。'],
  王霸: ['元伯', '?–59', '字元伯，颍川颍阳人，少为狱吏。刘秀经过颍阳，他率宾客从军，昆阳之战有功。河北时宾客多散去，唯独他留下，刘秀说“疾风知劲草”。王郎追兵在后，到呼沱河无船，他诡称冰坚可渡，众人赶到河边果然冰合得渡。后为讨虏将军，屯守上谷二十余年，与匈奴、乌桓大小数十百战，封淮陵侯。云台二十八将之一。'],
  马援: ['文渊', '前14–49', '字文渊，扶风茂陵人，少有大志，曾说“**后汉书|丈夫为志，穷当益坚，老当益壮**”。王莽末年流寓陇右，为隗嚣绥德将军，先后见公孙述、光武，说“**后汉书|当今之世，非独君择臣也，臣亦择君矣**”，劝隗嚣归汉未果，遂投光武。光武亲征陇右时聚米为山谷指画形势，后任陇西太守招抚诸羌。建武十七年为伏波将军南征交趾，斩征侧、征贰，封新息侯。晚年请击五溪蛮，病死于壶头山，被梁松诬陷，追收印绶，有“薏苡明珠”之谤。'],
  邓骘: ['昭伯', '?–121', '字昭伯，邓训长子，邓太后之兄。殇帝、安帝时以车骑将军辅政，与太后定策迎立安帝。永初元年羌乱，他率五营及诸郡兵屯汉阳，在冀西被钟羌击败，仍被拜为大将军，主张放弃凉州，被虞诩驳回。他谦恭自守，推进贤士杨震、朱宠、陶敦等，屡辞封赏，以母丧请求辞职，太后从班昭之议许之。太后崩后被宦官与王圣诬陷谋废立，免官归郡，与子邓凤绝食而死。'],
  侯览: ['', '?–172', '山阳防东人，桓帝时为中常侍，因参与诛梁冀封高乡侯，贪婪放纵，前后夺人宅舍三百八十一所、田地一百一十八顷，起立第宅十六区，又为母亲修建高大坟冢。山阳督邮张俭破其冢宅、籍没资财，上书劾奏，被他扣下，他反诬张俭结党，引发第二次党锢之祸。熹平元年因专权骄奢被劾，自杀。'],
  胡广: ['伯始', '91–172', '字伯始，南郡华容人，以孝廉试章奏为天下第一。他历事安、顺、冲、质、桓、灵六帝三十余年，一登司空，二作司徒，三为太尉，又为太傅，熟悉朝章典故，京师谚曰“万事不理问伯始，天下中庸有胡公”。但他谦恭谨慎，依违于外戚、宦官之间，质帝死后附和梁冀立桓帝，坐视李固、杜乔被害，为清议所讥。'],
  马腾: ['寿成', '?–212', '字寿成，扶风茂陵人，马援之后，父亲与羌女所生。他身长八尺余，体貌雄伟，性贤厚，人多敬之。中平年间随韩遂等起兵反汉，后与韩遂结为异姓兄弟，又相互攻伐。曹操以钟繇镇抚关中，他遣子马超随钟繇击破郭援、高干。建安十三年入朝为卫尉，家属迁往邺城。马超起兵反曹，次年他与在邺的家族二百余口被诛。'],
  袁术: ['公路', '?–199', '字公路，汝南汝阳人，袁绍的从弟，以侠气闻名，举孝廉，为虎贲中郎将。董卓废立时他出奔南阳，据有其众，与袁绍不和，结公孙瓒以抗袁绍、刘表。初平四年被曹操击败，走九江，据寿春。他相信“代汉者当涂高”之谶，建安二年称帝，国号仲家，奢淫无度，江淮之间人民相食，孙策与他断绝。此后屡败于吕布、曹操，部众离散，建安四年欲北投袁谭不得，裴注引《吴书》说他“**三国志|呕血斗余，遂死**”。'],
  吕布: ['奉先', '?–199', '字奉先，五原九原人，以骁武给并州，为丁原主簿。董卓入洛阳，诱他杀丁原，誓为父子，以为骑都尉。初平三年与王允合谋刺杀董卓，旋被李傕、郭汜逐出长安，依袁术、张杨、袁绍，都不能相容。兴平元年张邈、陈宫迎他为兖州牧，与曹操在濮阳相持，后被击败，投奔刘备，又乘机袭取下邳，自领徐州。建安三年被曹操围于下邳，部将缚陈宫投降，他在白门楼被擒，请降不得，与陈宫一同被缢杀。'],
  高干: ['元才', '?–206', '字元才，陈留圉人，袁绍的外甥，有才志。袁绍据冀州后以他领并州刺史。袁绍死后他依附袁尚，曾与郭援进攻河东，被钟繇、马超击败。建安九年曹操破邺，他以并州投降，仍为刺史；次年趁曹操北征乌桓，执上党太守，据壶关反叛。建安十一年曹操亲征，围壶关三月而拔，他南逃荆州，途中被上洛都尉王琰所杀。'],
  孔融: ['文举', '153–208', '字文举，鲁国人，孔子二十世孙，十岁时随父至洛阳，拜见河南尹李膺，自称“先君孔子与君先人李老君同德比义”，为时人所称。少年时藏匿张俭，兄弟争死。后为北海相，立学校，表儒术，被黄巾所围时太史慈为他突围求救。献帝都许后为少府、太中大夫，宾客日盈其门，常言“坐上客恒满，尊中酒不空”。他屡次讥讽曹操，建安十三年被路粹诬奏，与妻子一同被杀。'],
  董昭: ['公仁', '156–236', '字公仁，济阴定陶人，先后事袁绍、张杨。献帝东归时他为曹操出谋，联络杨奉，劝曹操迁都许县，又协助平定吕布、袁绍。他首倡曹操进位魏公、加九锡，后又建议进爵魏王，是曹氏代汉的主要谋划者之一。魏国时任卫尉、太常、司徒，明帝时上疏抨击浮华交游之风。'],
  诸葛瑾: ['子瑜', '174–241', '字子瑜，琅邪阳都人，诸葛亮之兄，避乱江东，经人推荐被孙权任用。建安二十年奉命出使蜀国求还荆州，与弟弟诸葛亮只在公事场合相见，退无私面。他容貌思度，时人服其弘雅，常以从容婉转之言劝谏孙权。夷陵之战前他写信劝刘备罢兵；后官至大将军、左都护，领豫州牧。其子诸葛恪后来主持吴国政事。'],
  轲比能: ['', '?–235', '鲜卑首领，出自小种鲜卑，因勇健、断法平端、不贪财物，被众人推为大人。他部落近塞，招纳逃亡的汉人，学作兵器铠楯，颇知文字，部众日盛，控弦十余万骑，每次抄掠所得财物均平分配，众人尽死力。建安年间曾随曹彰征乌桓时请服，后与步度根等互相攻伐，又与诸葛亮约定配合北伐，屡寇魏国北边。青龙三年被幽州刺史王雄派勇士韩龙刺杀，鲜卑诸部再度离散。'],
  孟达: ['子度', '?–228', '字子度，扶风郿人，建安初与法正入蜀依刘璋。刘备入蜀后归附，与刘封攻取上庸。关羽围樊城时请他与刘封发兵相助，二人以山郡初附为由推辞，关羽败亡后，他畏罪率部曲四千余家降魏，被曹丕任为新城太守，宠遇甚厚。曹丕死后，他心不自安，与诸葛亮、孙权暗通，图谋叛魏，司马懿自宛城倍道兼行，八日到达新城城下，围城十六日破之，将其斩首。'],
  刘晔: ['子扬', '?–234', '字子扬，淮南成德人，东汉阜陵王刘延之后，十三岁时手刃谗害其母的侍者。他先依扬州刘勋，后归曹操。曹操平定汉中后，他与司马懿劝曹操乘胜取蜀，曹操不听。魏国时任侍中，善于料事，孙权称藩时他力主趁机伐吴，未被采纳。明帝时深受信任，后因被疑两面逢迎而失宠，发狂而卒。'],
  臧霸: ['宣高', '?–?', '字宣高，泰山华人，少有孝烈之名。黄巾起后随陶谦击破黄巾，后聚众屯据开阳，与孙观、吴敦等结为泰山豪帅集团，曾依附吕布。吕布败后他藏匿起来，曹操搜获后加以重用，委以青、徐二州之事，使他镇抚东方，曹操得以专心对付袁绍。此后屡从征伐，曹丕时任镇东将军，进爵开阳侯。'],
  曹仁: ['子孝', '168–223', '字子孝，曹操的从弟，少好弓马弋猎，汉末聚少年千余人周旋淮泗之间，后归曹操。随曹操征伐，屡有战功。赤壁战后留守江陵，与周瑜相持一年有余，亲自率数十骑突围救出部将牛金，众人叹为“天人”。建安二十四年在樊城被关羽围困，于禁七军覆没，城中仅数千人，城墙不没者数板，他与将士誓死固守，等到徐晃来救。曹丕即位后官至大司马，黄初四年卒。'],
  夏侯玄: ['太初', '209–254', '字太初，夏侯尚之子，曹爽的表弟，少知名，弱冠为散骑黄门侍郎，风格高朗，弘辨博畅，与何晏等并为正始名士的领袖，时人称其“肃肃如入廊庙中”。正始年间任中护军，主持武官选举，后为征西将军、都督雍凉，随曹爽伐蜀失利。高平陵之变后被征回京师，任太常，失去兵权。嘉平六年中书令李丰等谋以他代司马师辅政，事泄被捕，临刑颜色不变，举动自若，被夷三族。'],
  步骘: ['子山', '?–247', '字子山，临淮淮阴人，避乱江东，家贫，与卫旌种瓜自给，昼勤四体，夜诵经传。孙权任他为主记、海盐长，建安十五年出任交州刺史，斩杀心怀异志的苍梧太守吴巨，士燮兄弟相率听命，交州始归孙吴。后率交州义士万人出长沙，平定零陵、桂阳。陆逊死后代为丞相，在西陵镇守二十年。'],
  张邈: ['孟卓', '?–195', '字孟卓，东平寿张人，少以侠闻，振穷救急，倾家无爱，与袁绍、曹操都是好友。初平元年为陈留太守起兵讨董卓，袁绍为盟主后有骄色，他正义责之，袁绍要曹操杀他，曹操不肯。后来他担心曹操终将听袁绍之言害己，兴平元年趁曹操东征徐州，与陈宫迎吕布为兖州牧。吕布被曹操击败后，他随吕布东走，在往袁术处求救途中被部下所杀，其弟张超守雍丘，城破，三族被夷。'],
  公孙康: ['', '?–221', '公孙度之子，建安九年继任辽东太守。他在朝鲜半岛北部分乐浪郡南部设置带方郡，又攻击高句丽。建安十二年袁尚、袁熙逃来投奔，他预先在厩中埋伏勇士，斩二人首级送给曹操，曹操封他为襄平侯、左将军。死后弟弟公孙恭继位，后来其子公孙渊夺位。'],
  袁熙: ['显奕', '?–207', '袁绍的次子，任幽州刺史。他的妻子甄氏留在邺城，邺城破后被曹丕所纳。袁尚兵败后投奔他，幽州部将焦触、张南叛变，二人逃往辽西乌桓蹋顿处。白狼山之战后又逃往辽东，被公孙康所杀，首级送给曹操。'],
  蹋顿: ['', '?–207', '辽西乌桓大人丘力居的侄子，丘力居死后因其子楼班年少而代立，总摄上谷、辽西、右北平三郡乌桓，有武略，众皆从其号令。袁绍与公孙瓒相持时，他遣使和亲，派兵助袁绍击破公孙瓒，袁绍矫制赐他单于印绶。袁绍死后，袁熙、袁尚投奔他，他数入塞为害，企图助袁氏收复故地。建安十二年曹操出卢龙塞奇袭柳城，在白狼山与他遭遇，张辽为先锋，将他斩杀，三郡乌桓从此衰落。'],
  曹奂: ['景明', '246–302', '本名曹璜，字景明，曹操之孙，燕王曹宇之子，封常道乡公。甘露五年曹髦被杀后，司马昭迎立十五岁的他为帝，改名曹奂，改元景元，政事尽决于司马氏。在位期间魏灭蜀，司马昭进爵晋王。咸熙二年十二月禅位于晋武帝司马炎，被封为陈留王，迁居邺城，享受天子礼乐，上书不称臣。太安元年卒，年五十八，谥元皇帝，魏国自此终结。'],
  李丰: ['安国', '?–254', '字安国，冯翊东人，卫尉李义之子，少有清白之名，魏明帝时已为人所称。嘉平四年任中书令，虽为司马师所亲，却常怀不平，与夏侯玄、皇后之父张缉交好，密谋以夏侯玄代司马师辅政。嘉平六年二月，趁贵人受封、天子临轩之时谋诛司马师，事泄，司马师召他面质，他痛斥司马师父子包藏奸心，被以刀环筑杀，父子兄弟皆被诛。'],
  司马炎: ['安世', '236–290', '字安世，司马昭长子，宽惠仁厚，沈深有度量。咸熙二年司马昭死，他继为晋王、相国，同年十二月受魏禅即皇帝位，国号晋，改元泰始，即晋武帝。在位期间颁行《泰始律》，罢州郡兵，推行占田、课田制。咸宁五年采纳羊祜遗策与杜预、王濬之议，六路伐吴，太康元年灭吴，结束了近百年的分裂。晚年怠于政事，耽于游宴，后宫近万人，又立痴愚的太子司马衷，分封宗室，太熙元年卒，死后不久天下大乱。'],
  陈敏: ['令通', '?–307', '字令通，庐江人，少有干能，以郡廉吏补尚书仓部令史，后任合肥、广陵度支，负责漕运。永安元年他率运兵击斩石冰，平定扬、徐二州，升任广陵相。见中原大乱，他于永兴二年在历阳起兵，自号楚公、都督江东军事，逼迫顾荣等江东士族接受官职，弟陈恢略取江州，据有吴越之地。他才能平庸，诸弟凶暴，永嘉元年顾荣、周玘、甘卓等倒戈，他兵败被斩，夷三族。'],
  顾荣: ['彦先', '?–312', '字彦先，吴郡吴人，吴丞相顾雍之孙，与陆机、陆云号为“三俊”。吴亡后入洛，历任郎中、尚书郎、廷尉正，见中原多乱，常纵酒以避祸。齐王冏时为主簿，后辞归江东。陈敏割据江东时，他被迫接受官职，暗中与周玘、甘卓等谋划，次年倒戈，以羽扇一挥，陈敏部众溃散。琅邪王司马睿渡江后，他率江东士族归附，为东晋立国出力甚多。'],
  周玘: ['宣佩', '258–313', '字宣佩，义兴阳羡人，周处之子，强毅沉断，有父风，闭门洁己，名重一方。太安年间石冰据扬州，他暗中联络王矩，推顾秘为都督，率江东士族起兵，攻杀石冰所置将吏，事成后散众还乡，不受封赏。永嘉元年又与顾荣合谋倒戈击灭陈敏，后来再平钱璯之乱，号称“三定江南”。东晋初年因受北方士族排挤，忧愤而死，临终嘱其子周勰为他报仇。'],
  刘琨: ['越石', '271–318', '字越石，中山魏昌人，汉中山靖王刘胜之后，少负志气，有纵横之才，善交胜己，与祖逖为友，闻鸡起舞。年轻时为贾谧二十四友之一，赵王伦时任其子的从事中郎，后随东海王越征战。光熙元年出任并州刺史，孤军坚守晋阳十年，抵抗刘渊、刘聪、石勒，联结拓跋猗卢，诗文悲壮。后兵败投奔幽州段匹磾，太兴元年被段匹磾缢杀。'],
  刘渊: ['元海', '?–310', '字元海，匈奴左部帅刘豹之子，幼好学，师事上党崔游，习《毛诗》《京氏易》《马氏尚书》，尤好《春秋左氏传》、孙吴兵法，又善骑射，膂力过人。曾为质子久居洛阳，武帝时王济等荐他可用，被孔恂、杨珧所阻。后任五部大都督，被成都王颖留在邺城。永兴元年回到左国城，被拥为大单于，二旬之间众至五万，以汉高祖嫁女冒顿为由，国号汉，称汉王，永嘉二年称帝，迁都平阳，为十六国之始。'],
  司马腾: ['元迈', '?–307', '字元迈，东海王越之弟，初封东嬴公，任并州刺史，镇晋阳。永安元年与王浚联兵讨伐成都王颖，次年匈奴刘渊起兵离石，他屡战屡败，并州饥荒，又掠卖胡人以充军饷，羯人石勒即在被卖之列。光熙元年进封东燕王，改镇邺城，率并州吏民万余人东下，号“乞活”。永嘉元年被汲桑、石勒攻破邺城时杀死。'],
  司马越: ['元超', '?–311', '字元超，司马懿之弟司马馗之孙，封东海王，少有令名，谦虚持布衣之操。太安二年与殿中诸将擒长沙王乂，开城迎降。永安元年奉惠帝讨伐成都王颖，在荡阴战败，逃回东海国。永兴二年在徐州起兵西迎大驾，联合王浚、祁弘击败河间王颙，光熙元年迎惠帝还洛，任太傅、录尚书事，独揽朝政，惠帝暴死，时人疑为他所毒杀。他是八王之乱的最后胜利者，此后专权数年。'],
  王衍: ['夷甫', '256–311', '字夷甫，琅邪临沂人，王戎从弟，神情明秀，风姿详雅，山涛见他说“误天下苍生者，未必非此人也”。他祖述何晏、王弼，崇尚玄虚，终日清谈老庄，手执玉柄麈尾，随时改正义理，世称“口中雌黄”，为西晋名士领袖，口不言钱，称之为“阿堵物”。历任尚书令、司空、司徒、太尉，只求自保，安排弟弟王澄、族弟王敦出镇荆、青。永嘉五年随东海王越东撤，被石勒俘获，推墙压杀。'],
  司马炽: ['丰度', '284–313', '字丰度，晋武帝第二十五子，封豫章王，冲素自守，门绝宾游，不交世事，专玩史籍，有誉于时。永兴元年张方劫惠帝入长安后，河间王颙废成都王颖，改立他为皇太弟。光熙元年惠帝暴死，他即位为晋怀帝，东海王越专擅朝政。永嘉五年洛阳被刘曜、石勒等攻破，他被俘至平阳，受刘聪羞辱，被迫青衣行酒，建兴元年被毒杀，年三十。'],
  祖逖: ['士稚', '266–321', '字士稚，范阳遒县人，世为北州豪族，性豁荡，不修仪检，轻财好侠，常散谷帛周济贫乏。后博览书记，与刘琨同为司州主簿，共被同寝，中夜闻鸡起舞，相约中原有事时各显身手。历任齐王冏、长沙王乂的属官，从惠帝北征荡阴。永嘉之乱后率亲党数百家南渡，建兴元年以奋威将军、豫州刺史渡江北伐，中流击楫而誓，收复黄河以南大片土地，大兴四年病逝于雍丘。'],
  王浚: ['彭祖', '252–314', '字彭祖，太原晋阳人，王沈之子，母亲出身微贱，以庶子袭爵。元康年间奉贾后之命与黄门孙虑共害愍怀太子，后都督幽州诸军事。他结好夷狄，以女妻鲜卑段务勿尘和乌桓苏恕延。永安元年联合东嬴公腾引鲜卑破邺，鲜卑大掠，沉妇女于易水者八千人。此后据幽州自重，又助东海王越击败河间王颙。永嘉之乱后骄奢僭越，谋称帝号，建兴二年被石勒诈降擒杀。'],
  陶侃: ['士行', '259–334', '字士行，鄱阳人，后徙居庐江寻阳，出身寒门，早孤贫，母亲湛氏截发换酒招待客人，为他结交名士。他任县吏，后被举孝廉入洛，受张华赏识。太安二年张昌作乱，荆州刺史刘弘以他为南蛮长史、大都护，累战破张昌，又击败陈敏部将钱端，由此以军功显名。东晋时平定杜弢、苏峻等乱，都督八州诸军事，镇武昌，勤于吏职，运甓习劳，官至太尉，封长沙郡公。'],
  慕容廆: ['弈洛瓌', '269–333', '字弈洛瓌，昌黎棘城鲜卑人，慕容涉归之子，幼而魁岸，美姿貌，张华见了说他“必为命世之器”。涉归死后其叔慕容耐篡位，他逃亡避祸，国人杀耐后迎立他。他先请求讨伐宇文部，被武帝拒绝后入寇辽西，太康六年袭破夫余，四年后归降晋朝，拜鲜卑都督，迁居徒河青山，元康四年移居大棘城，教民农桑，法制同于中原。此后收纳流亡士人，奠定前燕基业。'],
  石勒: ['世龙', '274–333', '字世龙，上党武乡羯人，部落小帅之子，年轻时并州饥荒，被东嬴公司马腾掳卖为奴，后与汲桑起兵，投奔刘渊，成为汉国大将。他重用谋士张宾，永嘉五年在苦县歼灭西晋主力，后据襄国，擒王浚，取并州。靳准之乱后与刘曜决裂，太兴二年称赵王，史称后赵，咸和三年亲征洛阳擒刘曜，次年灭前赵，五年称帝。他不识字而好听人读史，兴学校，定九品，咸和八年卒。'],
  石虎: ['季龙', '295–349', '字季龙，石勒的从子，自幼由石勒之父抚养，故被视为石勒之弟。他性残忍，好驰猎，少时以弹弓射人为乐，石勒一度想杀他。成年后骁勇善战，为石勒攻城略地，擒段匹磾、灭曹嶷、破刘岳，又在咸和四年进屠上邽，灭亡前赵，每破城常坑杀降卒。石勒死后他杀石弘自立，在位期间大兴土木，暴虐无度。'],
  王导: ['茂弘', '276–339', '字茂弘，琅邪临沂人，少有风鉴，识量清远。他与司马睿交好，劝其出镇建邺，为他结交顾荣、贺循等江东名士，安抚南北士族，被誉为“江左管夷吾”。元帝即位时请他同坐御床，时称“王与马，共天下”。王敦作乱时他率宗族待罪宫门，平乱后历辅明帝、成帝三朝，为政务在宽简，以清静镇之。苏峻之乱后力主不迁都，咸康五年卒，年六十四。'],
  郗鉴: ['道徽', '269–339', '字道徽，高平金乡人，汉御史大夫郗虑之玄孙，少孤贫，博览经籍，以清节著称。永嘉之乱时被推为乡里坞主，率千余家避难峄山，坚守数年，后率部南下，任兖州刺史，镇合肥、京口。明帝时参与平定王敦，苏峻之乱时自京口率兵渡江，在白石筑垒，与陶侃、温峤合击苏峻，官至太尉。他选王羲之为婿，即“东床快婿”的典故。'],
  庾亮: ['元规', '289–340', '字元规，颍川鄢陵人，明帝皇后之兄，美姿容，善谈论，好老庄。明帝时任中书令，参与平定王敦。成帝即位后以帝舅身份与王导共同辅政，执法严峻，猜忌宗室和流民帅，不顾王导、温峤劝阻，征召苏峻入朝，激起苏峻之乱，兵败后逃奔温峤，与陶侃、温峤联兵平乱。此后出镇芜湖、武昌，都督六州诸军事，曾谋北伐，咸康六年卒。'],
  司马衍: ['世根', '321–342', '字世根，晋明帝长子，五岁即位，即晋成帝，由庾太后临朝，王导、庾亮辅政。咸和三年苏峻攻陷建康，他被逼迁居石头，苏峻平定后才得出城。长大后颇留心政务，崇尚节俭。苏峻乱后他问庾亮“白头公”南顿王司马宗何在，庾亮说已以谋反伏诛，他哭着说“舅言人作贼，便杀之，人言舅作贼，复若何”。咸康八年病逝，年二十二。'],
  李雄: ['仲俊', '274–334', '字仲俊，李特第三子，身长八尺三寸，美容貌，少以烈气闻。李特、李流相继死后被推为首领，太安二年闰十二月攻克成都，罗尚弃城而逃。永兴元年称成都王，除晋法，约法七章，光熙元年在范长生劝说下称帝，国号大成。他在位三十年，兴学校，置史官，薄赋敛，刑政宽简，当中原丧乱之际，巴蜀独安。咸和九年病卒，庙号太宗。'],
  桓温: ['元子', '312–373', '字元子，谯国龙亢人，宣城内史桓彝之子，豪爽有风概，娶明帝之女南康长公主。父亲死于苏峻之乱，他十八岁手刃仇人之子，名震一时。永和元年任荆州刺史，三年灭成汉，十年北伐关中至灞上，十二年收复洛阳，屡请迁都洛阳。兴宁年间推行庚戌土断，太和四年伐燕败于枋头，此后废黜晋帝司马奕，立简文帝，权倾朝野，晚年谋求九锡，被谢安、王坦之拖延，宁康元年病死。'],
  司马奕: ['延龄', '342–386', '字延龄，晋成帝次子，哀帝同母弟，封琅邪王。兴宁三年哀帝死后即位，桓温专擅朝政。太和四年桓温伐燕在枋头大败，威名受挫，为重树权威，太和六年诬称他阳痿不能生育，其子皆宫中宠臣所生，逼褚太后下令将他废为东海王，后降为海西县公，迁居吴县，他从此纵酒自娱，以免猜忌，太元十一年卒。'],
  郗超: ['景兴', '336–378', '字景兴，郗鉴之孙，卓荦不羁，有旷世之度，善谈论，深通佛理。他是桓温的心腹谋士，人称“髯参军”。太和四年桓温伐燕，他建议直趋邺城或屯兵河济，桓温不从，终败于枋头。他又为桓温策划废黜司马奕、拥立简文帝以立威，权倾朝野，谢安、王坦之也要拜谒等候。他早于其父郗愔去世，临终把替桓温谋划的书信交给门生，嘱其父若过哀则呈上。'],
  谢安: ['安石', '320–385', '字安石，陈郡阳夏人，少有重名，神识沉敏，风宇条畅，善行书。他屡辞征召，隐居会稽东山，与王羲之、孙绰、支遁等游山玩水，时人说“安石不肯出，将如苍生何”。四十余岁才出仕为桓温司马，后任吏部尚书，与王坦之一道抵制桓温篡位。桓温死后执掌朝政，淝水之战时坐镇建康，指挥谢玄等以少胜多，官至太保，太元十年卒。'],
  苻坚: ['永固', '338–385', '字永固，苻洪之孙，苻雄之子，八岁请师就学，博学多才艺，有经济大志。升平元年杀苻生自立，称大秦天王，重用王猛，整饬吏治，抑制豪强，兴修水利，劝课农桑，关中大治。太和五年灭前燕，此后又灭前凉、代国，攻取梁益，统一北方。他宽仁待降，厚待慕容垂、姚苌等，太元八年南伐东晋，在淝水大败，各族相继叛离，太元十年被姚苌所杀。'],
  王猛: ['景略', '325–375', '字景略，北海剧县人，少贫贱，以卖畚为业，博学好兵书，谨重严毅，气度雄远。桓温入关时他披褐求见，扪虱而谈，桓温请他南归，他不肯。苻坚即位后倚为心腹，委以国政，他执法严明，诛除不法权贵，一年中迁官五次，前秦大治。太和五年率军灭前燕，又伐前凉、仇池。宁康三年病重，临终劝苻坚不要伐晋，应提防鲜卑、羌人，年五十一。'],
  慕容垂: ['道明', '326–396', '字道明，慕容皝第五子，身长七尺七寸，手垂过膝，少有器度，慕容皝爱之，名为霸，后改名垂。他随军攻破丸都，屡立战功，慕容儁忌之。慕容恪临终称其将相之才十倍于己，太和四年他在枋头大破桓温，威名大振，却遭慕容评和可足浑太后迫害，投奔前秦，受苻坚厚待。淝水之战后起兵复国，建立后燕，太元二十一年征北魏途中病死。'],
  慕容暐: ['景茂', '350–384', '字景茂，慕容儁第三子，升平四年以十一岁即位，前期由慕容恪辅政，国势强盛。慕容恪死后，政事落入慕容评与可足浑太后之手，朝政腐败，又逼走慕容垂。太和五年前秦王猛攻破邺城，他出逃被擒，被苻坚迁往长安，封新兴侯。淝水之战后他暗中联络鲜卑谋杀苻坚，事泄被杀。'],
  姚苌: ['景茂', '330–393', '字景茂，羌人首领姚弋仲第二十四子，姚襄之弟，少聪哲，多权略。姚襄战死后他降前秦，屡立战功，随苟苌灭前凉。淝水战后他在渭北起兵，自称万年秦王，建立后秦。太元十年在新平缢杀苻坚，次年入长安称帝。他与前秦苻登在关陇连年交战，晚年据说梦见苻坚率鬼兵入宫，惊惧患病，太元十八年死，其子姚兴继位。'],
  苻登: ['文高', '343–394', '字文高，苻坚的族孙，少而雄勇，有壮气，粗险不修细行。苻坚死后他在陇东被推为首领，太元十一年苻丕死后即皇帝位，载苻坚神主于军中，每战必告，与后秦姚苌在关陇连年交战，将士在铠甲上刻“死休”二字。太元十九年在马毛山被姚兴击败杀害。'],
  慕容永: ['叔明', '?–394', '字叔明，前燕慕容廆之弟慕容运的孙子，前燕亡后被迁往长安，曾以卖靴为业。他随慕容冲起兵，慕容冲死后西燕屡易其主，他率鲜卑四十余万口东归，太元十一年在襄陵大破前秦苻丕，进据长子即皇帝位，屠戮慕容儁、慕容垂的子孙，西燕在并州立国。太元十九年被后燕慕容垂攻灭，被杀。'],
  慕容宝: ['道佑', '355–398', '字道佑，慕容垂第四子，少轻果，无志操，好人佞己。淝水战后他劝慕容垂杀苻坚，慕容垂不从。后燕建立后被立为太子，慕容垂死后即帝位。太元二十年他率军伐北魏，在参合陂大败，数万燕军被坑杀，次年北魏攻破中山，他逃往龙城，隆安二年被舅父兰汗所杀。'],
  拓跋珪: ['', '371–409', '鲜卑拓跋部人，代王什翼犍之孙。代国被前秦攻灭时他年仅六岁，随母贺氏辗转依附独孤部、贺兰部。前秦瓦解后，太元十一年他被诸部拥立，在牛川即代王位，旋改国号为魏，史称北魏，迁居盛乐，息众课农。此后他先后击败独孤、贺兰诸部和柔然，在参合陂大败后燕，攻取中山、邺城，定都平城，称帝，是北魏道武帝。晚年服寒食散，性情暴躁，被其子拓跋绍所杀。'],
  司马曜: ['昌明', '362–396', '字昌明，晋简文帝第三子，十一岁即位，即晋孝武帝，初由褚太后临朝，桓冲、谢安先后辅政。在位期间谢安当国，谢玄组建北府兵，太元八年淝水之战大败前秦，东晋收复河南与梁益，国势一度振兴。谢安死后他与弟弟会稽王司马道子嗜酒荒政，宠信僧尼佞幸，太元二十一年醉后戏言张贵人年近三十当废，当夜被张贵人令宫婢用被子闷死，年三十五。'],
  司马道子: ['道子', '364–403', '晋简文帝之子，孝武帝同母弟，封会稽王。谢安死后执掌朝政，与孝武帝嗜酒荒政，宠信王国宝等佞臣，卖官鬻爵，宗室与王恭、殷仲堪等方镇不和。孝武帝死后他专擅朝政，其子司马元显继之，激起王恭、桓玄起兵与孙恩之乱。元兴元年桓玄攻入建康，杀司马元显，将他流放安成，次年毒杀。'],
  吕光: ['世明', '338–399', '字世明，略阳氐人，前秦太尉吕婆楼之子，身长八尺四寸，目重瞳子，沉毅凝重，宽简有大量，王猛称他非常人。太元八年受命率军七万西征，大破龟兹，西域诸国归附，得高僧鸠摩罗什。东归途中得知前秦瓦解，太元十年入据姑臧，自称凉州刺史，后称凉州牧、酒泉公，又称三河王、天王，史称后凉。隆安三年病死。'],
  刘牢之: ['道坚', '?–402', '字道坚，彭城人，世以武功为将，面紫赤色，须目惊人，沉毅多计划。谢玄组建北府兵时以骁猛应选，任参军，领精锐为前锋，百战百胜。淝水之战前夕他率五千人夜袭洛涧，斩秦将梁成，为大胜奠定基础。此后成为北府兵统帅，先后背叛王恭、司马元显，元兴元年又欲背桓玄，众叛亲离，自缢而死。'],
  谢琰: ['瑗度', '352–400', '字瑗度，谢安次子，弱冠以贞干称，美风姿。淝水之战时以辅国将军随谢石、谢玄出征，劝谢石从朱序之言速战，以功封望蔡公。后任会稽内史，隆安年间孙恩起兵攻会稽，他轻敌不备，被部下张猛所杀，两个儿子也一同遇害。'],
  鸠摩罗什: ['', '344–413', '龟兹人，父为天竺人，母为龟兹王之妹，七岁随母出家，遍游罽宾、疏勒，通大小乘经论，名扬西域。太元年间吕光攻破龟兹，将他带回凉州，被吕光父子羁留十余年。后秦姚兴灭后凉后迎他入长安，奉为国师，在逍遥园主持译经，译出《金刚经》《法华经》《中论》等三百余卷，弟子数千，对中国佛教影响深远。'],
  刘裕: ['德舆', '363–422', '字德舆，小字寄奴，彭城绥舆里人，家贫，曾以卖草鞋为业。他投身北府军，在镇压孙恩时以少击众，屡建战功。元兴三年在京口起兵讨灭桓玄，掌握朝政，此后灭南燕、平卢循、杀刘毅、平谯蜀、灭后秦，收复青兖、洛阳、关中，威震南北。元熙二年受晋禅，建立宋朝，即宋武帝，在位三年，永初三年病死，年六十。'],
  司马德文: ['德文', '386–421', '字德文，晋孝武帝次子，安帝同母弟，封琅邪王，性恭谨，常侍奉在愚钝的安帝左右。他随刘裕北伐后秦，修谒洛阳五陵。义熙十四年刘裕缢杀安帝，立他为帝，即晋恭帝，改元元熙。元熙二年刘裕令傅亮讽示禅位，他欣然书写诏书，说“晋氏久已失之，今复何恨”，退位后被封为零陵王，次年被刘裕派人用被子闷死，东晋亡。'],
  刘义真: ['', '407–424', '刘裕次子，美仪貌，神情秀彻。义熙十三年刘裕灭后秦后，留年仅十二岁的他镇守长安。次年夏国赫连勃勃来攻，关中晋将内讧，他奉命撤回，部众贪载财宝，行动迟缓，在青泥被夏军追及，全军覆没，只身逃回。入宋后封庐陵王，宋少帝时被权臣徐羡之等废杀。'],
  傅亮: ['季友', '374–426', '字季友，北地灵州人，傅咸的玄孙，博涉经史，尤善文辞。他是刘裕的亲信，起草诏令，参与机密。元熙二年他承刘裕密旨，讽示晋恭帝禅位，草拟禅让诏书。入宋后任中书令，与徐羡之、谢晦共同辅政，废杀宋少帝，迎立宋文帝，元嘉三年被宋文帝诛杀。'],
  檀道济: ['', '?–436', '高平金乡人，少孤，居丧以孝闻。他随刘裕讨伐桓玄，屡立战功。义熙十二年北伐后秦，他为前锋，攻克许昌、洛阳，所向披靡，以宽厚待降人，深得民心。入宋后官至司空，镇守寻阳，威名甚重，元嘉十三年被宋文帝猜忌，以谋反罪诛杀，临死怒道“乃坏汝万里长城”。'],
  陶潜: ['渊明', '365–427', '字渊明，一说名渊明字元亮，浔阳柴桑人，陶侃的曾孙，少有高趣，博学善属文，作《五柳先生传》自况。他家贫，先后任江州祭酒、镇军参军、建威参军，义熙元年为彭泽令，不愿束带见督邮，说“吾不能为五斗米折腰”，任职八十余日便解印归田，作《归去来》。此后躬耕于柴桑，屡辞征召，作《饮酒》《桃花源记》等诗文，开创田园诗派。入宋后所作诗文只题甲子，不书宋朝年号，元嘉四年卒，年六十三，颜延之为他作诔，私谥靖节先生。'],
  拓跋嗣: ['', '392–423', '北魏道武帝拓跋珪长子。北魏有立子杀母的制度，他的母亲刘氏被赐死，他哀泣不止，拓跋珪大怒，他出逃避祸。义熙五年其弟拓跋绍杀死拓跋珪，他率众回宫诛杀拓跋绍，即帝位，是为明元帝。他在位期间整顿吏治，修建长城防御柔然，刘裕北伐时一度出兵骚扰。泰常八年病死，年三十二。'],
  赫连勃勃: ['屈孑', '381–425', '字屈孑，匈奴铁弗部首领刘卫辰之子，身长八尺五寸，腰带十围，聪辩美风仪。北魏灭刘卫辰后他投奔后秦，姚兴以他为安北将军镇朔方。义熙三年背秦自立，国号大夏，改姓赫连，以骑兵游击侵扰后秦岭北。他役使民夫蒸土筑统万城，锥入一寸即杀筑者。义熙十四年夺取长安，在灞上称帝，以残忍好杀著称。晚年他想废太子赫连璝，诸子相攻，元嘉二年病死，年四十五，子赫连昌继位，六年后夏为北魏和吐谷浑所灭。'],
  乞伏炽磐: ['', '?–428', '西秦乞伏乾归之子，勇略过人。乞伏乾归被后秦降服后，他随父辗转，义熙五年西秦复国。义熙八年乞伏乾归被侄子乞伏公府所杀，他诛杀公府，即位为河南王。义熙十年乘南凉秃发傉檀西征之机，袭取乐都，灭南凉。此后与北凉、夏连年交战，西秦一度称雄陇西。元嘉五年病死，子乞伏暮末继位，三年后西秦为夏所灭。'],
  沮渠蒙逊: ['', '368–433', '临松卢水胡人，世为部落酋长，博涉群史，颇晓天文，雄杰有英略。隆安元年因叔父被吕光冤杀，与堂兄沮渠男成起兵，推段业建北凉，隆安五年杀段业，自称北凉州牧，后与南凉、西凉连年交战。义熙八年迁都姑臧，称河西王，此后灭西凉，统一河西，崇信佛教，开凿天梯山石窟。元嘉十年病死。'],
  冯跋: ['文起', '?–430', '字文起，长乐信都人，汉人，祖上迁居上党，后燕时任中卫将军。慕容熙暴虐，冯跋与其弟冯素弗等发动政变，杀慕容熙，拥立高云。义熙五年高云被杀，他诛杀凶手，即天王位，以龙城为都，史称北燕。他勤于政事，劝课农桑，省减徭役，与北魏、柔然周旋，在位二十二年。元嘉七年他病重，其弟冯弘率兵入宫，他惊惧而死，冯弘尽杀其子，自立为天王。'],
  刘骏: ['休龙', '430–464', '字休龙，小字道民，宋文帝第三子，封武陵王，元嘉末任江州刺史。元嘉三十年刘劭弑父自立，他在寻阳起兵讨伐，四月在新亭即帝位，即宋孝武帝，五月攻克建康，诛杀刘劭。在位期间削弱宗王，任用寒人为中书舍人以掌机要，平定刘义宣、臧质、刘诞的叛乱，奢侈好色，大明八年病死，年三十五。'],
  刘义恭: ['', '413–465', '宋武帝第五子，封江夏王，幼而明颖，姿颜美丽，最得宋武帝钟爱。刘义康被废后他任司徒、录尚书事，处事谨慎以自保。元嘉二十七年北伐时他总统诸军出镇彭城，北魏太武帝兵临城下，他闭城自守。刘劭弑立后，他弃家逃奔刘骏，刘劭杀其十二子。孝武帝时任太宰，宋前废帝时被杀，年五十三。'],
  柳元景: ['孝仁', '406–465', '字孝仁，河东解人，少便弓马，随父征战。元嘉二十七年北伐时为随王刘诞部将，率西路军出卢氏，攻克弘农、陕城，在陕城大破北魏援军，进据潼关，关中豪杰纷纷响应。东路王玄谟兵败后，宋文帝下诏撤军，他全师而还。元嘉三十年为刘骏前锋，在新亭大败刘劭。孝武帝时官至尚书令，宋前废帝时谋废立，事泄被杀，年六十。'],
  王玄谟: ['彦德', '388–468', '字彦德，太原祁人，自称王昶之后，少有大志。他屡次上书陈说北伐之策，宋文帝说听他陈说“使人有封狼居胥意”。元嘉二十七年他率前锋北伐，围攻滑台数月不下，北魏太武帝率大军南渡黄河救援，他弃军而逃，几乎被斩，后被免官。宋孝武帝即位后复起，历任要职，宋明帝时官至车骑将军，泰始四年病死，年八十一。'],
  沈庆之: ['弘先', '386–465', '字弘先，吴兴武康人，少有膂力，不识字，四十岁后才以军功显名，屡次平定雍州蛮族。元嘉二十七年宋文帝议北伐，他力陈不可，说“耕当问奴，织当访婢”，宋文帝不听。元嘉三十年他支持刘骏起兵讨伐刘劭，拥立孝武帝，封始兴郡公，官至太尉。宋前废帝荒淫，他屡次进谏，被赐毒药而死，年八十。'],
  宗悫: ['元干', '?–465', '字元干，南阳涅阳人，叔父宗炳是著名隐士。他少年时宗炳问其志向，他说“愿乘长风破万里浪”。元嘉二十三年随檀和之讨伐林邑，制作狮子形象击溃林邑象军，攻入林邑都城，所获珍宝一无所取。元嘉三十年随刘骏讨伐刘劭，孝武帝时官至豫州刺史、左卫将军，宋前废帝时去世。'],
  臧质: ['含文', '400–454', '字含文，东莞莒人，宋武帝敬皇后之侄，少好鹰犬，善蒲博，长于武艺。元嘉二十七年北魏南侵，他率万人救援寿阳，兵败后退入盱眙，与太守沈璞坚守，北魏太武帝向他索酒，他封尿送去，又回信讥讽，魏军围城三十日不克而退。元嘉三十年他与刘义宣起兵讨刘劭。孝建元年他与刘义宣举兵反叛孝武帝，兵败被杀，年五十五。'],
  拓跋濬: ['', '440–465', '北魏太武帝之孙，太子拓跋晃之子，自幼聪达，太武帝十分喜爱，常带在身边。正平二年宗爱弑杀太武帝、又杀拓跋余后，陆丽、源贺等迎他即位，年仅十三，即北魏文成帝。他诛杀宗爱，下诏恢复佛法，以昙曜为沙门统，开凿云冈石窟，与民休息，和平六年病死，年二十六。'],
  陆丽: ['', '?–465', '代人，北魏大臣陆俟之子，以忠谨入侍宫中，任尚书。正平二年宗爱杀拓跋余后，他与殿中尚书长孙渴侯、源贺、刘尼等迎立皇孙拓跋濬，诛杀宗爱，因功封平原王。文成帝死后权臣乙浑专权，他从代郡温泉回朝奔丧，被乙浑所杀。'],
  高允: ['伯恭', '390–487', '字伯恭，勃海蓨人，少孤，曾出家为僧，后还俗，博通经史天文术数。北魏太武帝时与崔浩共修国史，国史之狱事发，太子拓跋晃教他推罪于崔浩，他坦承书中多是自己所写，太武帝感其诚直而免其死。此后历仕五朝，屡上谏书，家贫，住草屋，食盐菜，孝文帝时官至光禄大夫，太和十一年卒，年九十八。'],
  萧宝卷: ['智藏', '483–501', '字智藏，齐明帝次子，永泰元年即位，即东昏侯。他不爱读书，喜好捕鼠嬉戏，诛杀顾命大臣，宠爱潘妃，凿金为莲花贴地，令潘妃行其上，说“此步步生莲华也”。他滥杀大臣，激起陈显达、崔慧景、萧衍相继起兵，永元三年萧衍围攻建康，他被部下所杀，年十九。'],
  陈显达: ['', '427–499', '南彭城人，出身寒微，以军功起家，宋末依附萧道成，在平定沈攸之时立功。入齐后屡任方镇，官至太尉，谦逊自持。永泰元年他率军北伐，收复马圈等地，孝文帝亲征，他兵败夜逃。东昏侯滥杀大臣，他心怀疑惧，永元元年冬在江州起兵，攻至建康城下，兵败被杀，年七十三。'],
  崔慧景: ['君山', '438–500', '字君山，清河东武城人，以武干知名，宋末依附萧道成。齐明帝时为将，建武五年救援雍州，与萧衍在邓城被魏军大败。东昏侯即位后滥杀大臣，他心怀恐惧，永元二年奉江夏王萧宝玄起兵，围攻建康台城，萧懿率援军赶到，他兵败被杀。'],
  萧衍: ['叔达', '464–549', '字叔达，小字练儿，南兰陵人，齐宗室，博学多才，为竟陵八友之一。齐明帝时任雍州刺史，镇守襄阳。齐东昏侯杀其兄萧懿，他在襄阳起兵，攻入建康，中兴二年受禅建梁，即梁武帝，在位四十八年，崇信佛教，四次舍身同泰寺。太清二年侯景叛乱，攻陷台城，他被困饿死，年八十六。'],
  沈约: ['休文', '441–513', '字休文，吴兴武康人，少孤贫，笃志好学，昼夜不倦，为竟陵八友之一，与谢朓等讲求四声八病，创永明体。他撰《宋书》一百卷，又著《四声谱》。齐末他劝萧衍代齐，入梁后官至尚书令，因言语触怒梁武帝，忧惧而死，年七十三。'],
  刘琦: ['', '?–209', '刘表长子，相貌与父亲相似，起初甚受宠爱。刘表后妻蔡氏宠爱少子刘琮，蔡瑁、张允等日夜毁谤刘琦，他求计于诸葛亮，诸葛亮以晋公子申生在内而危、重耳在外而安相劝，他于是请出为江夏太守。建安十三年刘表死，刘琮降曹，他据江夏与刘备会合，共拒曹操。赤壁之战后刘备表他为荆州刺史，次年病死。'],
  刘璋: ['季玉', '?–219', '字季玉，江夏竟陵人，刘焉幼子。兴平元年刘焉死，州中大吏赵韪等贪其温仁，共上书推他为益州刺史。他与张鲁不和，杀张鲁母弟，张鲁据汉中自立。他性格懦弱，对曹操时附时离，建安十六年听从张松、法正之议，迎刘备入蜀讨张鲁，次年刘备反攻，围成都数十日，城中尚有精兵三万，谷帛支一年，他说父子在州二十余年，无恩德以加百姓，百姓攻战三年，肌膏草野者，以璋故也，遂出城投降。后被孙权以为益州牧，不久病卒。', ['qunxiong', 'chibi']],
  王琳: ['子珩', '526–573', '字子珩，会稽山阴人，出身兵家，其姊妹为梁元帝宠姬，以军功起家，轻财爱士，部下多为江淮勇士。他随王僧辩平定侯景，江陵陷落后据湘、郢，奉梁元帝之孙萧庄为主与陈对抗。天嘉元年在梁山大败，投奔北齐。太建五年吴明彻北伐，他守寿阳，城破被杀，传首建康，寿阳百姓多为之哭泣。'],
  // 同名异人：与曹魏经学家王肃（195–256，卷十九）同名，只用于孝文、六镇两卷
  王肃: ['恭懿', '464–501', '字恭懿，琅邪临沂人，王导之后，齐秘书丞。其父王奂被齐武帝所杀，他于太和十七年投奔北魏，孝文帝与他谈论治道，相见恨晚。他熟悉朝章典故，为北魏制定礼仪、官制，又率军与齐作战。孝文帝临终遗诏他与元禧、元勰等辅政，后任扬州刺史，镇守寿春，景明二年卒。', ['xiaowen', 'liuzhen']],
  元勰: ['彦和', '473–508', '字彦和，北魏献文帝之子，孝文帝之弟，封彭城王，敏而耽学，雅好属文。孝文帝南征时他常侍左右，太和二十三年孝文帝病重，他侍奉汤药，日夜不离，孝文帝死于谷塘原，他秘不发丧，护送灵柩至鲁阳才发丧，迎宣武帝即位。永平元年被高肇诬陷，赐死，年三十六。'],
  元恪: ['', '483–515', '北魏孝文帝次子，太和二十一年太子元恂被废后立为太子，太和二十三年即位，即宣武帝。在位期间外戚高肇专权，元勰、元禧等宗室相继被杀；他崇信佛教，在洛阳大兴佛寺，开凿龙门石窟，又与梁争夺淮南、汉中，夺取寿春、梁州。延昌四年病死，年三十三。'],
  高欢: ['贺六浑', '496–547', '字贺六浑，渤海蓨人，祖父因罪徙居怀朔镇，遂习鲜卑之俗。他先后投奔杜洛周、葛荣，后归尔朱荣，屡立战功。尔朱荣死后他率六镇降户东出，普泰元年在信都起兵，次年在韩陵大破尔朱氏，入洛立孝武帝。孝武帝西奔后他另立孝静帝，迁都邺城，掌控东魏十余年，与西魏宇文泰连年交战。武定五年病死，年五十二，其子高洋建北齐后追尊为神武帝。'],
  宇文泰: ['黑獭', '507–556', '字黑獭，代郡武川人，鲜卑宇文部之后。六镇起事时随父参加鲜于修礼、葛荣，后归尔朱荣，随贺拔岳平定关陇。永熙三年贺拔岳被杀，他被部众推为主帅，讨灭侯莫陈悦，迎孝武帝入长安，又鸩杀孝武帝，立元宝炬为帝，建立西魏，此后在沙苑、邙山与高欢反复交战，创立府兵制。西魏恭帝三年病死，年五十，其子宇文觉建北周后追尊为文帝。'],
  元修: ['孝则', '510–535', '字孝则，北魏孝文帝之孙，广平王元怀第三子，封平阳王。韩陵之战后高欢立他为帝，即孝武帝。他不甘受制于高欢，联络关中贺拔岳，永熙三年七月率轻骑西奔长安投宇文泰，北魏由此分裂。他与宇文泰不和，同年闰十二月被宇文泰鸩杀，年二十五。'],
  元善见: ['', '524–552', '北魏孝文帝曾孙，清河王元亶的世子。永熙三年孝武帝西奔后，高欢立他为帝，即东魏孝静帝，年十一，随即迁都邺城。他好文学，美容仪，力能挟石狮子逾墙，但政事全由高欢父子掌握，曾说“自古无不亡之国，朕亦何惜此生”。武定八年禅位于高洋，东魏亡，次年被毒死。'],
  阿那瓌: ['', '?–552', '柔然可汗，姓郁久闾，正光元年因内乱投奔北魏，被封为朔方郡公、蠕蠕王，次年返回漠北，复立为可汗，号敕连头兵豆伐可汗。孝昌元年他应北魏之请，率十万骑击败破六韩拔陵。此后柔然复强，东魏、西魏都与之和亲。西魏废帝元年被突厥土门击败，自杀。'],
  陈霸先: ['兴国', '503–559', '字兴国，小字法生，吴兴长城人，出身寒微，好读兵书，初为乡里司、油库吏，后随萧映到广州，以平交州李贲之乱知名。侯景之乱时他自岭南北上，与王僧辩会师，攻克建康。江陵陷落后，他袭杀王僧辩，立梁敬帝，又击退北齐大军，太平二年受禅建陈，即陈武帝。在位三年，永定三年病死，年五十七。'],
  高洋: ['子进', '526–559', '字子进，高欢次子，外表木讷，常被兄长高澄轻视。武定七年高澄遇刺，他从容平乱，接掌朝政，次年逼东魏孝静帝禅位，建立北齐，即文宣帝。即位之初他留心政务，北伐柔然、契丹、山胡，修筑长城，北齐一度强盛；后期沉湎酒色，残暴嗜杀，天保十年病死，年三十四。'],
  宇文毓: ['统万突', '534–560', '字统万突，宇文泰庶长子，宽明仁厚，博览群书，善属文。孝闵帝被废后宇文护立他为帝，即北周明帝，初称天王，后改称皇帝，建元武成。他聪明有识，宇文护归政后亲览庶政，宇文护怕他难以控制，武成二年派人在糖饼中下毒，他临终口授遗诏传位于弟宇文邕，年二十七。'],
  宇文护: ['萨保', '513–572', '字萨保，宇文泰之兄宇文颢之子，少时随叔父宇文泰征战，为其心腹。宇文泰死后他受遗命辅政，逼西魏恭帝禅位，立宇文觉为天王，建立北周。他专擅朝政十五年，先后废杀孝闵帝宇文觉、毒杀明帝宇文毓，立武帝宇文邕。天和七年宇文邕在宫中亲手将他击杀。'],
  韦孝宽: ['孝宽', '509–580', '名叔裕，以字行，京兆杜陵人，沉敏和正，涉猎经史。大统十二年高欢倾山东之众围攻玉壁，他坚守六十日，以种种手段破解东魏的土山、地道、攻车，高欢久攻不下，忧愤发病。北周时镇守边境，以反间计使北齐冤杀名将斛律光。大象二年率军平定尉迟迥之乱，同年卒，年七十二。'],
  尉迟迥: ['薄居罗', '516–580', '字薄居罗，代人，宇文泰的外甥，少聪敏，美容仪。承圣二年萧纪东下争位，他奉宇文泰之命率军乘虚南下，围攻成都，萧纪的守将萧撝出降，益州入于西魏。北周时任相州总管，大象二年杨坚辅政，他起兵反对，被韦孝宽击败，自杀，年六十五。'],
  颜之推: ['介', '531–?', '字介，琅邪临沂人，世以儒学传家，博览群书，好饮酒，多任纵，不修边幅。侯景之乱时他在郢州被俘，几乎被杀，后投奔江陵，任散骑侍郎。承圣三年江陵陷落，被西魏掳往关中，后冒险乘船经砥柱之险逃奔北齐，又历仕北周、隋。晚年著《颜氏家训》二十篇，追述侯景之乱、江陵陷落的亲身经历。'],
  杨素: ['处道', '544–606', '字处道，弘农华阴人，少落拓，有大志，善属文，工草隶。他随北周武帝平齐，隋初任信州总管，在永安造五牙大舰，开皇八年为行军元帅率水军自巴东顺流东下，破陈军于狼尾滩、岐亭。开皇十年江南叛乱，他泛海追击，前后百余战平定江南。后官至尚书左仆射，监造仁寿宫，劳役严苛，又协助杨广夺嫡、构陷太子杨勇。隋炀帝即位后率军平定汉王杨谅，官至司徒，大业二年卒，年六十三。'],
  杨坚: ['', '541–604', '小字那罗延，弘农华阴人，杨忠之子，其女杨丽华为北周宣帝皇后。大象二年宣帝死后他以外戚辅政，平定尉迟迥、司马消难、王谦三方之乱，次年受禅建隋，即隋文帝。在位期间营建大兴城，定开皇律，创三省六部制，推行科举，击破突厥，废后梁，开皇九年灭陈，统一全国。仁寿四年病死于仁寿宫，年六十四。'],
  杨广: ['', '569–618', '一名英，小字阿摩，隋文帝次子，封晋王，美姿仪，少敏慧，好学善属文。开皇八年他以行军元帅统率五十余万大军伐陈，次年攻克建康，灭陈。后夺嫡为太子，仁寿四年即位，即隋炀帝，营建东都、开凿大运河、三征高句丽，役使无度，天下大乱，大业十四年在江都被宇文化及等缢杀，年五十。'],
  宇文恺: ['安乐', '555–612', '字安乐，朔方夏州人，北周功臣宇文贵之子，家世武将，他却好学博览，尤善工艺。隋初任营新都副监，规划设计大兴城；开皇四年主持开凿广通渠。隋炀帝时又规划营建东都洛阳，制作观风行殿等，官至工部尚书，大业八年卒，年五十八。'],
  高颎: ['昭玄', '541–607', '字昭玄，渤海蓨人，明敏有器局，涉猎文史，尤善词令。杨坚辅政时引为相府司录，平尉迟迥时任监军，烧桥背水而战。隋初任尚书左仆射，执政近二十年，参与营建大兴城，定伐陈之策，以晋王杨广元帅长史身份实际主持平陈之役。后因反对废太子杨勇被免官，隋炀帝时因议论朝政被杀，年六十七。'],
  长孙晟: ['季晟', '552–609', '字季晟，河南洛阳人，善弹工射，矫捷过人。北周时护送千金公主嫁突厥，在突厥一年，熟悉其山川形势与各部关系。隋初他上书建议远交近攻、离强合弱，以离间之计使阿波可汗、达头可汗与沙钵略相攻，突厥由此分裂为东西两部。后又扶立启民可汗，大业五年卒，年五十八，其女为唐太宗文德皇后。'],
  贺若弼: ['辅伯', '544–607', '字辅伯，河南洛阳人，少慷慨有大志，骁勇善骑射，博涉书记。隋初任吴州总管，献平陈十策。开皇九年正月他从广陵渡江，攻克京口，在钟山大破陈军，擒萧摩诃，因韩擒虎先入建康而与之争功。后因自负功高、言语怨望屡被免官，大业三年被隋炀帝杀害，年六十四。'],
  苏威: ['无畏', '542–623', '字无畏，京兆武功人，苏绰之子，少有令名。杨坚辅政时被高颎推荐，隋初任纳言、度支尚书，与高颎同掌朝政，主持制定律令、减轻赋役，时称“苏、高”。隋炀帝时官至左光禄大夫，后入唐，武德六年卒，年八十二。'],
  李渊: ['叔德', '566–635', '字叔德，陇西成纪人，北周唐国公李昞之子，母为独孤皇后之姊，七岁袭爵。隋末任太原留守，大业十三年在太原起兵，入长安立代王杨侑，次年受禅建唐，即唐高祖，年号武德。在位期间削平群雄，统一全国，定均田、租庸调与《武德律》。武德九年玄武门之变后传位于李世民，为太上皇，贞观九年病死，年七十。'],
  李世民: ['', '598–649', '李渊次子，少聪睿，有胆识。大业十一年应募赴雁门勤王，后随父在太原，与刘文静等谋划起兵，霍邑之战力谏不退。唐初封秦王，率军平定薛仁杲、刘武周、王世充、窦建德、刘黑闼，武德九年发动玄武门之变，杀太子李建成、齐王李元吉，即位为唐太宗，开贞观之治，灭东突厥，被尊为天可汗，贞观二十三年死，年五十二。'],
  李建成: ['', '589–626', '小字毗沙门，李渊长子。李渊太原起兵时他从河东赶来，任左领军大都督，攻西河、霍邑，率军守潼关，入长安后封唐王世子，唐建立后立为皇太子，曾平定刘黑闼。他与齐王李元吉联合，与功高的秦王李世民争夺储位，武德九年在玄武门被李世民射杀，年三十八。'],
  刘文静: ['肇仁', '568–619', '字肇仁，彭城人，倜傥有器略，隋末任晋阳令，因与李密联姻被下狱，李世民入狱探望，他劝李世民起兵。他与李世民谋划太原起兵，又出使突厥求得始毕可汗的兵马，任大将军府司马。唐初任纳言，随李世民征薛举，他自认才能功劳在裴寂之上而地位不及，心怀怨望，武德二年被诬谋反，被杀，年五十二。'],
  裴寂: ['玄真', '570–629', '字玄真，蒲州桑泉人，隋末任晋阳宫副监，与李渊交好，常与之饮酒博戏。他以晋阳宫宫女私侍李渊，又献出宫中米粮、甲仗，劝李渊起兵，任大将军府长史。唐建立后任尚书右仆射，深得高祖宠信，“视朝必引与同坐”，但不善用兵，曾被刘武周大败。贞观初被免官流放，后召还途中病死。'],
  李密: ['玄邃', '582–619', '字玄邃，京兆长安人，北周八柱国李弼的曾孙，好读书，曾骑牛读《汉书》。大业九年为杨玄感出谋，兵败后亡命，投奔瓦岗翟让，大海寺之战击杀张须陀，次年袭取兴洛仓，称魏公，围逼东都，众至数十万。他杀翟让后众心离散，童山之战击败宇文化及，却被王世充大败于邙山，入关降唐，武德元年十二月叛唐，被唐将盛彦师伏杀，年三十七。'],
  窦建德: ['', '573–621', '贝州漳南人，少重然诺，任里长时曾倾家为乡人办丧事。隋末因藏匿逃兵被杀尽家属，投奔高士达，高士达死后统领其众，礼贤下士，不杀俘获的隋官，河北士人多归附。大业十三年称长乐王，次年称夏王，定都乐寿，后迁洺州，擒杀宇文化及。武德四年率兵救援王世充，在虎牢被李世民击败被俘，押至长安被杀。'],
  王世充: ['行满', '?–621', '字行满，本西域胡人，其祖母改嫁王氏，因姓王，《隋书》避唐太宗讳作“王充”。他颇涉经史，好兵法，善于揣摩人意，任江都通守时以奉迎得炀帝宠信，又镇压江淮起事者。大业末奉命援救东都，与李密相持；皇泰元年他发动政变杀元文都等，独揽东都大权，次年逼皇泰主禅位，国号郑。武德四年被李世民围困出降，被仇家所杀。'],
  宇文化及: ['', '?–619', '宇文述之子，性凶险，不循法度，好乘肥挟弹，长安人称“轻薄公子”。炀帝时任右屯卫将军，大业十四年随驾在江都，与弟宇文智及、司马德戡等利用骁果思归作乱，弑杀炀帝，立秦王杨浩，自称大丞相，率众北归，被李密在童山击败，退至魏县称帝，国号许，次年被窦建德擒杀。'],
  杨侗: ['仁谨', '604–619', '字仁谨，隋炀帝之孙，元德太子杨昭之子，封越王，炀帝巡幸江都时留守东都，抵御李密的围攻。大业十四年炀帝死讯传来，东都留守官拥立他为帝，改元皇泰，史称皇泰主，以段达、王世充、元文都等为七贵辅政。次年王世充逼他禅位，不久将他毒死，年十六。'],
  萧皇后: ['', '?–647', '后梁明帝萧岿之女，开皇二年嫁晋王杨广，炀帝即位后立为皇后。她性情婉顺，好学解属文，见炀帝失德而不敢直谏，作《述志赋》自寄。江都之变后她被宇文化及、窦建德辗转挟持，后被突厥处罗可汗的义成公主迎往突厥。贞观四年唐灭东突厥，她回到长安，贞观二十一年死去。'],
  李轨: ['处则', '?–619', '字处则，武威姑臧人，家富，好赈济穷乏，乡里称之。隋末任鹰扬府司马，薛举起兵后他与曹珍、关谨等起兵，自称河西大凉王，据有河西五郡，后称帝。他起初与唐通好，后不肯称臣；境内饥荒时听信巫者之言不肯开仓赈济，人心离散，武德二年被胡人安兴贵、安修仁兄弟擒送长安处死。'],
  刘武周: ['', '?–622', '马邑人，骁勇善射，好结交豪侠，任鹰扬府校尉，与马邑太守王仁恭的侍婢私通。大业十三年他杀王仁恭起兵，依附突厥，被始毕可汗立为定杨可汗，攻占楼烦、雁门、定襄，后称帝。武德二年以宋金刚为将南下，攻陷太原，尽取河东，次年被李世民在介休击败，北逃突厥，后被突厥所杀。'],
  梁师都: ['', '?–628', '夏州朔方人，世为郡中豪族，隋末任鹰扬郎将。大业十三年杀郡丞唐世宗起兵，攻取雕阴、弘化、延安等郡，称帝，国号梁，依附突厥，受封大度毗伽可汗。他屡次引突厥入寇，是隋末群雄中最后被平定的一家，贞观二年唐军围攻朔方，被其堂弟梁洛仁所杀。'],
  萧铣: ['', '583–621', '后梁宣帝萧詧的曾孙，少孤贫，以外戚任罗县县令。大业十三年被董景珍等拥立为梁王，次年称帝，迁都江陵，据有荆、湘、岭南，拥兵四十万。他猜忌功臣，诛杀董景珍等，部众离心。武德四年李孝恭、李靖率军顺江东下，围攻江陵，他出降，被押到长安处死，年三十九。'],
  林士弘: ['', '?–622', '饶州鄱阳人，大业十二年随同乡操师乞起兵，操师乞战死后代领其众，大破隋将刘子翊，自称皇帝，国号楚，建元太平，据有九江、庐陵、豫章等地，北至九江、南及番禺。后被萧铣所部击败，势力渐衰，武德五年遣使降唐，不久又叛，在安成山洞中病死。'],
  杜伏威: ['', '?–624', '齐州章丘人，少豪荡，与同乡辅公祏结为生死之交，十六岁起事，转战江淮，大业十三年渡淮攻陷历阳，自称总管。他兼并江淮诸部，击败李子通、陈棱，据有江东。武德二年降唐，封吴王，赐姓李，武德五年入朝长安，留京不返，辅公祏乘机在丹阳反叛，他也受牵连，武德七年暴死于长安。'],
  义成公主: ['', '?–630', '隋朝宗室之女，开皇十九年嫁启民可汗，此后依突厥习俗先后嫁给始毕、处罗、颉利三位可汗。大业十一年始毕可汗袭击隋炀帝，她遣使告变，又诈称北边有警促使始毕解雁门之围。隋亡后她迎萧皇后入突厥，屡劝可汗攻唐为隋复仇，贞观四年唐灭东突厥，她被唐军杀死。'],
  伏允: ['', '?–635', '吐谷浑可汗，开皇十七年其兄世伏被国人所杀，他继位，依俗娶隋光化公主。他常窥伺隋朝虚实，大业五年被隋炀帝亲征击败，率数十骑南遁，故地被隋设为四郡；隋末大乱时复其故地，屡寇唐边。贞观九年李靖率军讨伐，他兵败西逃，被部下所杀。'],
  薛举: ['', '?–618', '河东汾阴人，侨居金城，家财巨万，骁勇善骑射，好结交豪杰。隋末任金城府校尉，大业十三年劫持县令起兵，自称西秦霸王，后称帝，徙都天水，与子薛仁杲攻掠陇右，拥兵十三万。武德元年在浅水原大败李世民，打算进取长安，不久病死，其子薛仁杲继位，同年被李世民所灭。'],
  沈法兴: ['', '?–620', '湖州武康人，世为郡中著姓，宗族数千家。隋末任吴兴太守，江都之变后以讨宇文化及为名起兵，据有江表十余郡，自称梁王，都于毗陵。他专尚威刑，将士稍有过失即斩，部下离心，武德三年被李子通击败，投奔吴郡途中被人所迫，自投江而死。'],
  罗艺: ['子延', '?–627', '字子延，襄阳人，寓居京兆云阳，性桀黠，刚愎不仁，勇于攻战，善射。隋末为虎贲郎将，守涿郡，江都之变后自称幽州总管。他拒绝窦建德、高开道的拉拢，以幽州归唐，被封为燕王，赐姓李。后随李建成讨刘黑闼，入朝任左翊卫大将军，与太子亲善。太宗即位后他心不自安，贞观元年在泾州诈称奉密诏起兵，兵败被部下所杀。'],
  李治: ['为善', '628–683', '字为善，唐太宗第九子，母长孙皇后，封晋王，性仁孝。贞观十七年太子承乾被废，经长孙无忌力争立为皇太子。贞观二十三年即位，即唐高宗，在位期间灭西突厥、百济、高句丽，唐疆域达到极盛；他立武则天为皇后，晚年苦于风疾，政事多委武后，二人并称“二圣”，弘道元年卒，年五十六。'],
  长孙无忌: ['辅机', '?–659', '字辅机，河南洛阳人，长孙晟之子，长孙皇后之兄，好学，该博文史。少与李世民为布衣之交，随太宗征战，参与谋划玄武门之变，功居第一。贞观中任吏部尚书、尚书右仆射、司空、司徒，主持修订《贞观律》，力主立晋王李治为太子，图形凌烟阁居首。高宗时以元舅辅政，反对立武则天为后，显庆四年被诬谋反，流放黔州，被逼自缢。'],
  褚遂良: ['登善', '596–658', '字登善，杭州钱塘人，博涉文史，工书法，楷书被誉为初唐四大家之一。贞观中任谏议大夫、黄门侍郎，以直言著称，曾谏阻太宗亲征高句丽。太宗临终与长孙无忌同受顾命。高宗时任尚书右仆射，因坚决反对立武则天为后，在殿上叩头流血，被贬潭州、桂州、爱州，显庆三年死于爱州。'],
  李勣: ['懋功', '594–669', '原名徐世勣，字懋功，曹州离狐人，家富多僮仆。十七岁投瓦岗翟让，劝翟让取兴洛仓，后归李密。李密降唐后，他以黎阳之地归唐，被赐姓李，避太宗讳改名李勣。随李世民平王世充、窦建德、刘黑闼，贞观四年与李靖共灭东突厥，镇守并州十六年，又灭薛延陀、征高句丽。高宗时官至司空，总章元年攻灭高句丽，次年卒，年七十六。'],
  程知节: ['义贞', '589–665', '本名咬金，字义贞，济州东阿人，骁勇善用马槊。隋末聚众保乡里，后投李密，邙山之战被王世充所获，后与秦叔宝等阵前降唐，归李世民帐下，参与平定窦建德、王世充、刘黑闼。玄武门之变时追随李世民，贞观中封卢国公，图形凌烟阁。高宗时任葱山道行军大总管讨伐西突厥，因纵军屠城被免官，麟德二年卒。'],
  禄东赞: ['', '?–667', '吐蕃大相，噶尔氏，性明毅严重，讲兵训师，雅有节制，松赞干布能统一吐蕃多赖其谋。贞观十四年他携黄金珍宝到长安请婚，应答得体，太宗欲以琅琊长公主的外孙女嫁他，他推辞不受。松赞干布死后他以大相专掌国政，向吐谷浑扩张，吐蕃由此强盛，乾封二年卒，其子钦陵继任。'],
  李显: ['', '656–710', '唐高宗第七子，武则天第三子，初名显，封英王，李贤被废后立为太子。弘道元年即位，即唐中宗，次年因要以韦玄贞为侍中被武后废为庐陵王，流放房州十四年，与韦氏相依为命。圣历元年被召回立为太子，神龙元年在张柬之等拥立下复位，复国号为唐，此后宠信韦后、安乐公主，景龙四年暴死，史家多疑为韦后所鸩。'],
  李旦: ['', '662–716', '唐高宗第八子，武则天幼子，初封殷王、豫王。嗣圣元年中宗被废后被立为帝，即唐睿宗，居于别殿，不得参预政事。天授元年武则天称帝，他被降为皇嗣，改姓武氏；圣历元年让太子位于李显。景云元年其子李隆基平定韦后之乱后，他再次即位，延和元年传位于李隆基，开元四年卒。'],
  武三思: ['', '?–707', '武则天之兄武元庆之子，善于逢迎，武周时封梁王，与武承嗣争谋储位，营州之乱时任榆关道安抚大使。神龙政变后他结交韦皇后、上官婉儿，排挤张柬之等五王，将他们贬死岭南，独揽朝政。景龙元年太子李重俊发动政变，带兵冲入其府中将他父子杀死。'],
  张柬之: ['孟将', '625–706', '字孟将，襄州襄阳人，进士及第，七十余岁时经狄仁杰两次推荐，被武则天任为洛州司马、秋官侍郎，八十岁拜相。神龙元年他与崔玄暐、桓彦范、敬晖、袁恕己联络羽林军，发动政变，诛杀张易之兄弟，拥立中宗复位，封汉阳王。后被武三思与韦后排挤，贬为新州司马，愤恚而死。'],
  默啜: ['', '?–716', '骨咄禄之弟，继位后自称迁善可汗。他先助武周讨契丹，袭破其后方，借机索取河曲六州降户与农具种子；圣历元年因武周以武延秀和亲而大怒，扣留武延秀，入寇河北，攻陷定、赵等州。他控弦四十万，东败契丹、奚，西击突骑施，北服铁勒诸部，后突厥达到极盛。晚年暴虐，开元四年北讨拔野古时被杀。'],
  李隆基: ['', '685–762', '唐睿宗第三子，即唐玄宗，性英断多艺，尤知音律。景龙四年他发动唐隆政变诛灭韦后，立为太子，先天元年受禅即位，次年诛太平公主。开元年间任用姚崇、宋璟、张说、张九龄等，整顿吏治，检括户口，改府兵为募兵，国力达到极盛，史称开元盛世。天宝以后宠爱杨贵妃，委政李林甫、杨国忠，边镇节度使拥兵自重，天宝十四载安禄山起兵，他逃往蜀中，太子李亨在灵武即位，尊他为太上皇，宝应元年卒，年七十八。'],
  杨贵妃: ['', '719–756', '名玉环，蒲州永乐人，幼年丧父，养于叔父杨玄璬家，善歌舞，通音律。开元二十三年册为寿王李瑁之妃，武惠妃死后被玄宗召入宫中，先出家为女道士，号太真，天宝四载册为贵妃，宠冠后宫，三姊封韩国、虢国、秦国夫人，族兄杨国忠任宰相。安禄山拜她为母。天宝十五载玄宗逃往蜀中，至马嵬驿，禁军杀杨国忠，她被缢死，年三十八。'],
  杨国忠: ['', '?–756', '本名钊，蒲州永乐人，杨贵妃的族兄，张易之的外甥，少时嗜酒好赌，为宗族所鄙。他从军蜀中，因贵妃得宠而被剑南节度使章仇兼琼荐入朝廷，善于计算，身兼四十余使，天宝九载赐名国忠。李林甫死后他任右相，掩盖两征南诏的惨败，与安禄山交恶，屡言其必反。安禄山以诛杨国忠为名起兵，次年他随玄宗出逃，在马嵬驿被禁军所杀。'],
  高力士: ['', '684–762', '本名冯元一，潘州人，岭南冯盎的曾孙，幼年被阉割送入宫中，由宦官高延福收为养子，改姓高。他在唐隆政变、先天之变中追随玄宗，任右监门卫将军，知内侍省事。玄宗把四方奏章先交他审阅，小事由他决断，太子称他为二兄，王公称他为翁。安史之乱后他随玄宗入蜀，回京后被李辅国排挤，流放巫州，宝应元年遇赦北归，听说玄宗已死，号恸吐血而死。'],
  哥舒翰: ['', '?–757', '突骑施哥舒部人，世居安西，父为安西副都护。他四十岁才赴河西从军，在王忠嗣部下以勇猛著称，善使半段枪。王忠嗣被贬后他继任陇右节度使，天宝八载以数万士卒的代价攻下石堡城，又收复九曲，封西平郡王。安禄山起兵后他抱病镇守潼关，被杨国忠逼迫出关作战，在灵宝西原大败，被部将火拔归仁执送安禄山，后被安庆绪所杀。'],
  高仙芝: ['', '?–756', '高句丽人，随父在安西从军，二十余岁即拜将军，美姿容，善骑射。天宝六载他率步骑一万翻越葱岭，攻破小勃律，擒其国王与吐蕃公主，升任安西四镇节度使。天宝九载他袭破石国，次年在怛罗斯被大食击败。安禄山起兵后他任副元帅守陕州，与封常清退守潼关，被监军边令诚诬告盗减军粮，与封常清一同被斩于潼关军中。'],
  李嗣业: ['', '?–759', '京兆高陵人，身长七尺，壮勇绝伦，天宝初应募至安西，善使陌刀，每战为先锋，所向必陷。天宝六载他随高仙芝攻小勃律，率陌刀手攻上连云堡；怛罗斯之战唐军大败时，他持大棒驱开拔汗那的溃兵，护高仙芝逃出。安禄山起兵后他率安西兵万里东援，在香积寺之战中持长刀身先士卒，收复两京，乾元二年围攻相州时中流矢而死。'],
  阁罗凤: ['', '712–779', '南诏王，皮逻阁之子，天宝七载嗣立。云南太守张虔陀侮辱其妻，又多方勒索，天宝九载他攻陷云南，杀张虔陀；次年与鲜于仲通战于西洱河，大破唐军，北臣吐蕃，被封为“赞普钟”，号东帝；天宝十三载又全歼李宓之军。他立《南诏德化碑》，自陈叛唐出于不得已，安史之乱时乘机攻取巂州，大历十四年卒。'],
  安禄山: ['', '703–757', '营州柳城胡人，本姓康，名轧荦山，母为突厥巫者，后随继父冒姓安。他通晓六蕃语言，曾为互市牙郎，被张守珪收为养子，因战功升任平卢节度使，又兼范阳、河东节度使，身兼三镇。他外表痴直而内藏狡黠，拜杨贵妃为母，深得玄宗宠信。天宝十四载以讨杨国忠为名在范阳起兵，次年在洛阳称大燕皇帝，攻陷长安，至德二载被其子安庆绪所杀。'],
  李适: ['', '742–805', '唐代宗长子，即唐德宗。宝应元年他以雍王为天下兵马元帅，会合回纥收复东京，在陕州因不肯向回纥可汗舞蹈而使属官被杖死。大历十四年即位，起用杨炎推行两税法，决意削藩，却引发四镇之乱与泾原兵变，出奔奉天、梁州，下罪己诏后才得还京。晚年猜忌大臣，重用宦官统领神策军，又广收进奉，设宫市，民间苦之，贞元二十一年卒，年六十四。'],
  刘晏: ['士安', '716–780', '字士安，曹州南华人，七岁举神童，为太子正字。安史之乱后他历任户部侍郎、吏部尚书，长期主持度支、盐铁、转运。他疏浚汴水，分段转运江淮漕粮，每年入关多至百余万石；改革盐法，实行就场专卖，盐利占天下赋税之半；又在各地设巡院，及时掌握物价，调节丰歉。德宗即位后被杨炎陷害，贬为忠州刺史，建中元年赐死，年六十五，天下以为冤。'],
  颜真卿: ['清臣', '709–784', '字清臣，琅邪临沂人，颜杲卿的从弟，开元年间进士及第。天宝末任平原太守，预料安禄山必反，暗中修城浚壕，安禄山起兵后他联合从兄颜杲卿起兵，被河北诸郡推为盟主。后来至凤翔见肃宗，因刚正不阿屡遭权臣排挤，历任刑部尚书、湖州刺史、吏部尚书，封鲁郡公，世称颜鲁公。兴元元年被卢杞陷害，奉命宣慰叛将李希烈，被缢杀，年七十六。他的楷书雄浑端庄，称为颜体。'],
  李晟: ['良器', '727–793', '字良器，洮州临潭人，世代为陇右裨将，十八岁从军，善骑射，王忠嗣称他为万人敌。大历十四年吐蕃、南诏合兵入寇西川，他率神策兵入蜀，大破联军。建中四年泾原兵变，德宗出奔奉天，他自河北回师，孤军收复长安，朱泚败逃被杀，封西平郡王，与郭子仪并称“郭李”。晚年被张延赏排挤，罢兵权，贞元九年卒，年六十七。'],
  赤松德赞: ['', '742–797', '吐蕃赞普，赤德祖赞之子，母为金城公主（一说为那囊氏），天宝十四载其父被大臣所杀，他年幼即位。他乘安史之乱、唐边兵东调之机，尽取河西陇右，广德元年一度攻入长安，立广武王李承宏为帝，此后连年入寇关中，又与南诏联兵进攻西川。他崇奉佛教，迎请寂护、莲花生入藏，建桑耶寺，贞元年间劫盟平凉，卒于贞元十三年。'],
  异牟寻: ['', '754–808', '南诏王，阁罗凤之孙，凤迦异之子，颇知书，有才智，善于抚众。大历十四年阁罗凤死后即位，同年与吐蕃合兵入寇西川，被李晟大败，迁都羊苴咩城。他苦于吐蕃征敛繁重，在西川节度使韦皋的招抚下，贞元十年在点苍山与唐使崔佐时会盟，弃吐蕃而复归唐，被册封为南诏王，又攻破吐蕃神川铁桥，元和三年卒。'],
  李宝臣: ['', '718–781', '本名张忠志，奚人，被安禄山收为养子，起兵后为恒州刺史。宝应元年他以恒、赵、深、定、易五州降唐，被任为成德军节度使，赐姓名李宝臣。他据有恒、定等七州，拥兵五万，与魏博、卢龙、淄青、山南东道相互结援，父死子继。晚年迷信方士，猜忌部将，杀害骁将十余人，建中二年饮方士所献甘露汤而死。'],
  李正己: ['', '733–781', '本名怀玉，高丽人，生于平卢，随侯希逸南渡至青州。永泰元年他驱逐侯希逸，自任平卢淄青节度使，后乘汴宋之乱夺取曹、濮等州，据有十五州之地，拥兵十万，在诸镇中最为强大，与田承嗣、李宝臣、梁崇义相互结援。建中二年他与诸镇连兵抗命，同年八月病死，其子李纳继位。'],
  田弘正: ['安道', '764–821', '本名兴，字安道，田承嗣之侄田庭玠之子，有勇力，读书颇多，性恭逊。他任魏博牙内兵马使，屡次规谏田季安。元和七年田季安死，军中拥他为留后，他以魏博六州归附朝廷，宪宗赐名弘正。此后他率魏博兵参与讨伐淮西、淄青，屡立战功。长庆元年移镇成德，被成德军将王庭凑所杀。'],
  李愬: ['元直', '773–821', '字元直，李晟之子，有谋略，善骑射。元和十一年他自请讨伐淮西，任唐邓节度使，到任后示弱以懈敌，善待降将李祐、吴秀琳，掌握蔡州虚实。元和十二年十月雪夜袭蔡州，四更登城，擒吴元济，淮西平定，任山南东道节度使，封凉国公。后又率武宁军讨伐李师道，长庆元年卒，年四十九。'],
  李恒: ['', '795–824', '唐宪宗第三子，即唐穆宗，元和七年立为太子。元和十五年宪宗暴死，宦官梁守谦、王守澄等拥立他即位。他耽于游宴，不亲政事，采纳宰相萧俛、段文昌“销兵”之议，裁减军队，河朔三镇随即复叛，宪宗平藩的成果丧失殆尽。长庆二年他打马球时中风，服食丹药，长庆四年卒，年三十。'],
  牛僧孺: ['思黯', '779–848', '字思黯，安定鹑觚人，隋朝牛弘的后代。元和三年他应贤良方正科，对策直言时政之失，触怒宰相李吉甫，长期不得升迁。穆宗、文宗时两度为相，主张对藩镇和吐蕃息事宁人，与李德裕相互排斥，形成牛李党争。武宗时被李德裕贬斥，宣宗即位后召回，大中二年卒，年七十。'],
  李漼: ['', '833–873', '本名温，唐宣宗长子，即唐懿宗。宣宗晚年迟迟不立太子，大中十三年宣宗病重，宦官王宗实等矫诏立他为太子，随即即位。他耽于游宴，迷信佛教，在位期间南诏屡次进犯安南、西川，浙东裘甫、徐州庞勋相继起事，咸通十四年迎佛骨入宫，同年卒，年四十一。'],
  张义潮: ['', '799–872', '又作张议潮，沙州敦煌人，世代为州将。吐蕃统治河西六十余年，他暗中结交豪杰，大中二年乘吐蕃内乱起兵，驱逐吐蕃守将，收复沙州，又相继收复瓜、伊、肃、甘等州，派使者辗转入朝。大中五年唐置归义军，以他为节度使，咸通二年他又收复凉州。咸通八年他入朝长安，由侄子张淮深代领归义军，咸通十三年卒于长安。'],
  酋龙: ['', '?–877', '又作世隆，南诏王丰祐之子。大中十三年丰祐死后他即位，因唐不遣使吊祭，又因其名犯唐玄宗讳而不予册封，便自称皇帝，国号大礼，改元建极，与唐断绝往来，派兵攻陷播州。此后他屡次攻陷安南，进犯西川，围攻成都，南诏国力也因连年征战而衰弱，乾符四年卒。'],
  卫瓘: ['伯玉', '220–291', '字伯玉，河东安邑人，魏晋重臣，以明识清允称。魏末以监军身份随钟会、邓艾伐蜀，与钟会构陷邓艾，钟会作乱后他平定乱兵，又派人追杀邓艾父子。入晋后都督幽州、青州诸军事，离间鲜卑、乌桓，官至司空、太保。他曾借醉抚御床说“此座可惜”，暗示太子不堪继位，由此得罪贾后。元康元年与汝南王亮共同辅政，被楚王玮矫诏收捕，与子孙九人同时遇害。他善草书，与索靖并称“一台二妙”。'],
  武则天: ['', '624–705', '名曌，并州文水人，武士彟之女，十四岁入宫为太宗才人。太宗死后在感业寺为尼，被高宗召回，永徽六年立为皇后，与高宗并称二圣。高宗死后她先后废中宗、立睿宗，临朝称制，平定徐敬业与宗室起兵，任用酷吏，天授元年改唐为周，自称圣神皇帝，是中国历史上唯一的女皇帝。她重视科举，提拔狄仁杰、姚崇等，神龙元年被迫传位中宗，同年死去，年八十二。'],
  薛仁贵: ['仁贵', '614–683', '名礼，字仁贵，以字行，绛州龙门人，少贫贱，以耕田为业。贞观十九年应募从征高句丽，在安市城下白衣持戟陷阵，被太宗擢用。高宗时随军击突厥、铁勒，“将军三箭定天山”；总章元年随李勣灭高句丽，留守安东；咸亨元年在大非川被吐蕃论钦陵大败，除名为民。晚年复起，再破突厥，永淳二年卒，年七十。'],
  李亨: ['', '711–762', '唐玄宗第三子，即唐肃宗，开元二十六年立为太子。天宝年间李林甫、杨国忠屡兴大狱动摇其地位，他两次被迫与妃子离婚以自保。安禄山攻破潼关，他随玄宗西逃，在马嵬驿被百姓挽留，北上灵武即位，任用郭子仪、李光弼，借回纥兵收复两京。他宠信张皇后与宦官李辅国，猜忌功臣，以宦官鱼朝恩监九节度之师，致有相州之败。宝应元年四月玄宗死后十三日，他在病中受惊而死，年五十二。'],
  陈玄礼: ['', '?–?', '唐隆政变时他以万骑果毅追随李隆基诛灭韦后，此后长期统领禁军，任龙武大将军，淳朴自检，深得玄宗信任。天宝十五载玄宗西逃，到马嵬驿时他认为祸乱由杨国忠而起，领禁军诛杀杨国忠，又请玄宗赐死杨贵妃，随后护送玄宗入蜀。上皇回长安后，他被李辅国逼令致仕，不久去世。'],
  李德裕: ['文饶', '787–850', '字文饶，赵郡人，宰相李吉甫之子，以门荫入仕，不喜科举。长庆元年他揭发科场请托，与李宗闵、牛僧孺结怨，牛李党争由此而起。他出镇浙西、西川，修筹边楼，收维州，颇有政绩。武宗时任宰相六年，破回鹘乌介可汗，平定泽潞刘稹，抑制宦官，裁汰冗官，主持会昌毁佛，封卫国公。宣宗即位后他被贬为潮州司马，再贬崖州司户，大中三年卒于崖州。'],
  李宗闵: ['损之', '?–846', '字损之，唐宗室郑王李元懿之后，贞元年间进士，元和三年与牛僧孺同应制科，对策指斥时政，触怒李吉甫。长庆元年他因女婿科场请托被贬，从此与李德裕结怨，与牛僧孺结为一党。文宗时两度为相，与李德裕交替进退，后因依附郑注被贬。武宗时被李德裕再贬为郴州司马，宣宗即位后量移，未行而卒。'],
  王守澄: ['', '?–835', '宦官，元和末任徐州监军、枢密使，相传与陈弘志合谋弑杀宪宗，拥立穆宗，后任右神策中尉。敬宗被弑后，他又率神策军诛刘克明，拥立文宗，专权跋扈。大和五年他诬告宰相宋申锡谋反。后来文宗任用他推荐的李训、郑注图谋宦官，大和九年他被夺兵权，赐鸩酒而死。'],
  李泌: ['长源', '722–789', '字长源，京兆人，七岁能文，以神童见称于玄宗。安史之乱时他以布衣身份辅佐肃宗，参与谋划，被称为“山人”，因遭李辅国等忌恨，归隐衡山。代宗、德宗时屡次被召，贞元三年任宰相，劝德宗北和回纥、南通南诏、西结大食与天竺以困吐蕃，又保全太子李诵，调和李晟、马燧等功臣与德宗的关系，贞元五年卒，年六十八。'],
  裴度: ['中立', '765–839', '字中立，河东闻喜人，贞元年间进士。元和十年任御史中丞时与武元衡同日遇刺，伤首未死，随即被任为宰相，力主讨伐淮西，元和十二年亲往前线督师，李愬入蔡州擒吴元济，封晋国公。此后他历事穆宗、敬宗、文宗，屡次出将入相，晚年因宦官专权，在洛阳筑绿野堂，与白居易、刘禹锡等饮酒赋诗，开成四年卒，年七十五。'],
  渊盖苏文: ['', '?–666', '又作泉盖苏文，高句丽权臣，世为东部大人。贞观十六年他发动政变，杀高句丽荣留王及大臣百余人，立王侄高藏为王，自任莫离支，独揽国政。他拒绝唐朝调停高句丽与新罗的争端，太宗于贞观十九年亲征，攻安市城不下而还，此后唐军屡次进攻都被他击退。乾封元年他死后，三个儿子渊男生、渊男建、渊男产相争，渊男生降唐，高句丽两年后灭亡。'],
};
const commonOf = (n, id) => { const c = Object.prototype.hasOwnProperty.call(PEOPLE_COMMON, n) ? PEOPLE_COMMON[n] : null; return c && (!c[3] || c[3].includes(id)) ? c : null; };
